CREATE OR REPLACE FUNCTION private.record_pos_inventory_movement(p_license_id uuid, p_product_id text, p_batch_id text DEFAULT NULL::text, p_sale_id text DEFAULT NULL::text, p_sale_item_id text DEFAULT NULL::text, p_movement_type text DEFAULT 'sale_out'::text, p_quantity numeric DEFAULT 0, p_previous_stock numeric DEFAULT NULL::numeric, p_new_stock numeric DEFAULT NULL::numeric, p_previous_batch_stock numeric DEFAULT NULL::numeric, p_new_batch_stock numeric DEFAULT NULL::numeric, p_unit_cost numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_source text DEFAULT 'sale'::text, p_actor_device_id uuid DEFAULT NULL::uuid, p_actor_staff_user_id uuid DEFAULT NULL::uuid, p_actor_key text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS pos_inventory_movements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.pos_inventory_movements;
  v_movement public.pos_inventory_movements;
  v_id text;
  v_unit_cost numeric := case when p_unit_cost is null then null else greatest(p_unit_cost, 0) end;
begin
  if p_license_id is null then
    raise exception 'INVENTORY_MOVEMENT_LICENSE_REQUIRED' using errcode = 'P0001';
  end if;
  if nullif(btrim(coalesce(p_product_id, '')), '') is null then
    raise exception 'INVENTORY_MOVEMENT_PRODUCT_REQUIRED' using errcode = 'P0001';
  end if;
  if coalesce(p_quantity, 0) <= 0 then
    raise exception 'INVENTORY_MOVEMENT_QUANTITY_INVALID' using errcode = 'P0001';
  end if;

  if p_idempotency_key is not null and btrim(p_idempotency_key) <> '' then
    select * into v_existing
    from public.pos_inventory_movements
    where license_id = p_license_id
      and idempotency_key = p_idempotency_key
    limit 1;

    if v_existing.id is not null then
      return v_existing;
    end if;
  end if;

  v_id := 'inv_mov_' || replace(gen_random_uuid()::text, '-', '');

  insert into public.pos_inventory_movements (
    id, license_id, product_id, batch_id, sale_id, sale_item_id,
    movement_type, quantity, previous_stock, new_stock,
    previous_batch_stock, new_batch_stock, unit_cost, total_cost,
    reason, source, actor_device_id, actor_staff_user_id, actor_key, actor_name,
    idempotency_key, metadata, server_version
  ) values (
    v_id, p_license_id, p_product_id, p_batch_id, p_sale_id, p_sale_item_id,
    coalesce(p_movement_type, 'sale_out'), p_quantity, p_previous_stock, p_new_stock,
    p_previous_batch_stock, p_new_batch_stock, v_unit_cost,
    case when v_unit_cost is null then null else p_quantity * v_unit_cost end,
    p_reason, coalesce(p_source, 'sale'), p_actor_device_id, p_actor_staff_user_id, p_actor_key, p_actor_name,
    nullif(btrim(coalesce(p_idempotency_key, '')), ''),
    coalesce(p_metadata, '{}'::jsonb),
    1
  )
  returning * into v_movement;

  return v_movement;
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_preview_cloud_sale_cancellation_legacy_r1(p_license_key text, p_device_fingerprint text, p_security_token text DEFAULT NULL::text, p_staff_session_token text DEFAULT NULL::text, p_sale_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_staff_user_id uuid;
  v_actor_key text;
  v_actor_name text;
  v_permissions jsonb;
  v_sale_id text := nullif(btrim(coalesce(p_sale_id, '')), '');
  v_sale public.pos_sales;
  v_sale_folio text;
  v_block_reasons jsonb := '[]'::jsonb;
  v_can_cancel boolean := true;
  v_requires_specific_permission boolean := false;
  v_has_specific_permission boolean := false;
  v_has_global_permission boolean := false;

  v_cash_original_count integer := 0;
  v_cash_original_amount numeric := 0;
  v_cash_original_movements jsonb := '[]'::jsonb;
  v_cash_missing_session_count integer := 0;
  v_cash_session_ids jsonb := '[]'::jsonb;
  v_sale_cash_component numeric := 0;
  v_sale_non_cash_component numeric := 0;

  v_inventory_original_count integer := 0;
  v_inventory_original_quantity numeric := 0;
  v_inventory_original_movements jsonb := '[]'::jsonb;
  v_inventory_missing_product_count integer := 0;
  v_inventory_missing_batch_count integer := 0;

  v_customer public.pos_customers;
  v_charge public.pos_customer_ledger;
  v_payment public.pos_customer_ledger;
  v_credit_debt_before numeric := 0;
  v_credit_debt_after numeric := 0;
  v_credit_reversal_amount numeric := 0;
  v_subsequent_payment_count integer := 0;
  v_subsequent_payments jsonb := '[]'::jsonb;
  v_credit_required boolean := false;
  v_cash_required boolean := false;
  v_inventory_required boolean := false;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  perform private.assert_cloud_sales_cancellations_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'pos');

  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := (v_context->>'device_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;
  v_actor_key := private.resolve_cash_actor_key(v_context);
  v_actor_name := private.resolve_cash_actor_name(v_context);
  v_permissions := coalesce(v_context->'staff_permissions', '{}'::jsonb);

  if v_sale_id is null then
    return jsonb_build_object(
      'success', false,
      'can_cancel', false,
      'code', 'SALE_ID_REQUIRED',
      'message', 'La venta a cancelar es obligatoria.',
      'block_reasons', jsonb_build_array(jsonb_build_object('code', 'SALE_ID_REQUIRED', 'message', 'La venta a cancelar es obligatoria.')),
      'mode', 'cloud_sale_cancellation_preview'
    );
  end if;

  select * into v_sale
  from public.pos_sales s
  where s.license_id = v_license_id
    and s.id = v_sale_id
  limit 1;

  if v_sale.id is null then
    return jsonb_build_object(
      'success', false,
      'can_cancel', false,
      'code', 'SALE_NOT_FOUND',
      'message', 'Venta no encontrada.',
      'block_reasons', jsonb_build_array(jsonb_build_object('code', 'SALE_NOT_FOUND', 'message', 'Venta no encontrada.')),
      'mode', 'cloud_sale_cancellation_preview',
      'actor', jsonb_build_object('actor_key', v_actor_key, 'actor_name', v_actor_name, 'device_id', v_device_id, 'staff_user_id', v_staff_user_id)
    );
  end if;

  v_sale_folio := coalesce(v_sale.cloud_folio, v_sale.folio, v_sale.local_folio, v_sale.id);

  if v_sale.source_mode <> 'cloud_committed' then
    v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'SALE_NOT_CLOUD_COMMITTED', 'message', 'Esta venta no fue confirmada en cloud.'));
  end if;

  if v_sale.status = 'cancelled' or v_sale.cancelled_at is not null then
    v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'SALE_ALREADY_CANCELLED', 'message', 'La venta ya fue cancelada anteriormente.'));
  elsif v_sale.status <> 'closed' then
    v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'SALE_NOT_CLOSED', 'message', 'Solo se pueden cancelar ventas cerradas.'));
  end if;

  if coalesce(v_context->>'device_role', 'staff') = 'staff' then
    v_requires_specific_permission := (v_permissions ? 'sales_cancellations') or (v_permissions ? 'cancel_sales');
    v_has_specific_permission := coalesce((v_permissions->>'sales_cancellations')::boolean, false)
      or coalesce((v_permissions->>'cancel_sales')::boolean, false);
    v_has_global_permission := coalesce((v_permissions->>'reports')::boolean, false)
      or coalesce((v_permissions->>'sales_cancellations_global')::boolean, false)
      or coalesce((v_permissions->>'all_sales')::boolean, false);

    if v_requires_specific_permission and not v_has_specific_permission then
      v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'POS_PERMISSION_DENIED:sales_cancellations', 'message', 'No tienes permiso para cancelar ventas.'));
    end if;

    if v_sale.staff_user_id is distinct from v_staff_user_id and not v_has_global_permission then
      v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'SALE_CANCELLATION_FORBIDDEN', 'message', 'No tienes permiso para cancelar esta venta.'));
    end if;
  end if;

  v_sale_cash_component := coalesce(nullif(v_sale.metadata #>> '{payment_summary,cash_component}', '')::numeric, 0);
  v_sale_non_cash_component := coalesce(nullif(v_sale.metadata #>> '{payment_summary,non_cash_component}', '')::numeric, 0);

  select
    count(*)::integer,
    coalesce(sum(abs(cm.amount)), 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'id', cm.id,
      'type', cm.type,
      'source', cm.source,
      'cash_session_id', cm.cash_session_id,
      'amount', abs(cm.amount),
      'concept', cm.concept,
      'customer_ledger_id', cm.customer_ledger_id,
      'created_at', cm.created_at
    ) order by cm.created_at asc, cm.id asc), '[]'::jsonb)
  into v_cash_original_count, v_cash_original_amount, v_cash_original_movements
  from public.pos_cash_movements cm
  where cm.license_id = v_license_id
    and cm.sale_id = v_sale.id
    and cm.deleted_at is null
    and cm.type in ('venta', 'venta_efectivo', 'abono_cliente')
    and cm.source not in ('sale_cancellation', 'sale_credit_cancellation');

  select count(*)::integer
  into v_cash_missing_session_count
  from public.pos_cash_movements cm
  left join public.pos_cash_sessions s
    on s.license_id = cm.license_id
   and s.id = cm.cash_session_id
   and s.deleted_at is null
  where cm.license_id = v_license_id
    and cm.sale_id = v_sale.id
    and cm.deleted_at is null
    and cm.type in ('venta', 'venta_efectivo', 'abono_cliente')
    and cm.source not in ('sale_cancellation', 'sale_credit_cancellation')
    and s.id is null;

  select coalesce(jsonb_agg(distinct cm.cash_session_id), '[]'::jsonb)
  into v_cash_session_ids
  from public.pos_cash_movements cm
  where cm.license_id = v_license_id
    and cm.sale_id = v_sale.id
    and cm.deleted_at is null
    and cm.cash_session_id is not null;

  v_cash_required := v_sale.cash_session_id is not null or v_cash_original_count > 0;

  if v_cash_required and v_cash_missing_session_count > 0 then
    v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'CASH_SESSION_NOT_FOUND', 'message', 'No se encontro una caja original de la venta.'));
  end if;

  select
    count(*)::integer,
    coalesce(sum(im.quantity), 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'id', im.id,
      'product_id', im.product_id,
      'batch_id', im.batch_id,
      'sale_item_id', im.sale_item_id,
      'quantity', im.quantity,
      'unit_cost', im.unit_cost,
      'created_at', im.created_at
    ) order by im.created_at asc, im.id asc), '[]'::jsonb)
  into v_inventory_original_count, v_inventory_original_quantity, v_inventory_original_movements
  from public.pos_inventory_movements im
  where im.license_id = v_license_id
    and im.sale_id = v_sale.id
    and im.movement_type = 'sale_out';

  select count(*)::integer
  into v_inventory_missing_product_count
  from public.pos_inventory_movements im
  left join public.pos_products p
    on p.license_id = im.license_id
   and p.id = im.product_id
   and p.deleted_at is null
  where im.license_id = v_license_id
    and im.sale_id = v_sale.id
    and im.movement_type = 'sale_out'
    and p.id is null;

  select count(*)::integer
  into v_inventory_missing_batch_count
  from public.pos_inventory_movements im
  left join public.pos_product_batches b
    on b.license_id = im.license_id
   and b.id = im.batch_id
   and b.product_id = im.product_id
   and b.deleted_at is null
  where im.license_id = v_license_id
    and im.sale_id = v_sale.id
    and im.movement_type = 'sale_out'
    and im.batch_id is not null
    and b.id is null;

  v_inventory_required := coalesce(v_sale.inventory_effect_status, 'not_applied') = 'applied' or v_inventory_original_count > 0;

  if v_inventory_required and v_inventory_missing_product_count > 0 then
    v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'PRODUCT_NOT_SYNCED_FOR_CLOUD_SALE', 'message', 'No se encontro un producto cloud para devolver inventario.'));
  end if;

  if v_inventory_required and v_inventory_missing_batch_count > 0 then
    v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'CLOUD_BATCH_NOT_AVAILABLE', 'message', 'No se encontro un lote cloud para devolver inventario.'));
  end if;

  v_credit_required := coalesce(v_sale.credit_effect_status, 'not_applied') = 'applied'
    or v_sale.credit_ledger_charge_id is not null
    or v_sale.credit_ledger_payment_id is not null;

  if v_credit_required then
    if v_sale.customer_id is null then
      v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'CREDIT_SALE_CUSTOMER_REQUIRED', 'message', 'La venta fiada no tiene cliente ligado.'));
    else
      select * into v_customer
      from public.pos_customers c
      where c.license_id = v_license_id
        and c.id = v_sale.customer_id
      limit 1;

      if v_customer.id is null then
        v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'CUSTOMER_NOT_FOUND', 'message', 'No se encontro el cliente de la venta fiada.'));
      end if;

      select * into v_charge
      from public.pos_customer_ledger l
      where l.license_id = v_license_id
        and l.deleted_at is null
        and (
          (v_sale.credit_ledger_charge_id is not null and l.id = v_sale.credit_ledger_charge_id)
          or (v_sale.credit_ledger_charge_id is null and l.sale_id = v_sale.id and l.type = 'CHARGE')
        )
      order by l.created_at asc
      limit 1;

      if v_charge.id is null then
        v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'CREDIT_CHARGE_LEDGER_NOT_FOUND', 'message', 'No se encontro el cargo de credito de la venta.'));
      end if;

      select * into v_payment
      from public.pos_customer_ledger l
      where l.license_id = v_license_id
        and l.deleted_at is null
        and (
          (v_sale.credit_ledger_payment_id is not null and l.id = v_sale.credit_ledger_payment_id)
          or (v_sale.credit_ledger_payment_id is null and l.sale_id = v_sale.id and l.type = 'PAYMENT')
        )
      order by l.created_at asc
      limit 1;

      select coalesce(sum(l.amount), 0)
      into v_credit_debt_before
      from public.pos_customer_ledger l
      where l.license_id = v_license_id
        and l.customer_id = v_sale.customer_id
        and l.deleted_at is null;

      select
        count(*)::integer,
        coalesce(jsonb_agg(jsonb_build_object(
          'id', q.id,
          'amount', abs(q.amount),
          'payment_method', q.payment_method,
          'reference_type', q.reference_type,
          'reference_id', q.reference_id,
          'cash_session_id', q.cash_session_id,
          'created_at', q.created_at,
          'note', q.note
        ) order by q.created_at asc, q.id asc), '[]'::jsonb)
      into v_subsequent_payment_count, v_subsequent_payments
      from (
        select l.*
        from public.pos_customer_ledger l
        where l.license_id = v_license_id
          and l.customer_id = v_sale.customer_id
          and l.deleted_at is null
          and l.type = 'PAYMENT'
          and l.amount < 0
          and coalesce(l.sale_id, '') <> v_sale.id
          and coalesce(l.metadata->>'reversal', 'false') <> 'true'
          and l.created_at > coalesce(v_charge.created_at, v_sale.committed_at, v_sale.created_at, v_sale.sold_at)
        order by l.created_at asc, l.id asc
        limit 20
      ) q;

      if v_subsequent_payment_count > 0 then
        v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object(
          'code', 'SALE_HAS_SUBSEQUENT_CUSTOMER_PAYMENTS',
          'message', 'La venta fiada tiene abonos posteriores independientes. No se cancelo automaticamente para evitar descuadrar la deuda.',
          'payment_count', v_subsequent_payment_count
        ));
      end if;

      if v_charge.id is not null then
        v_credit_debt_after := v_credit_debt_before + coalesce(abs(v_payment.amount), 0) - abs(v_charge.amount);
        if v_credit_debt_after < -0.005 then
          v_block_reasons := v_block_reasons || jsonb_build_array(jsonb_build_object('code', 'CUSTOMER_DEBT_NEGATIVE_AFTER_CANCEL', 'message', 'La deuda del cliente quedaria negativa despues de cancelar.'));
        end if;
        v_credit_debt_after := greatest(v_credit_debt_after, 0);
        v_credit_reversal_amount := greatest(abs(v_charge.amount) - coalesce(abs(v_payment.amount), 0), 0);
      end if;
    end if;
  end if;

  v_can_cancel := jsonb_array_length(v_block_reasons) = 0;

  return jsonb_build_object(
    'success', true,
    'can_cancel', v_can_cancel,
    'code', case when v_can_cancel then 'OK' else coalesce(v_block_reasons #>> '{0,code}', 'CLOUD_SALE_CANCELLATION_BLOCKED') end,
    'message', case when v_can_cancel then 'La venta puede cancelarse de forma segura.' else 'La venta no puede cancelarse automaticamente.' end,
    'sale', private.pos_sale_to_jsonb(v_sale),
    'folio', v_sale_folio,
    'reason_previewed', v_reason,
    'block_reasons', v_block_reasons,
    'preview', jsonb_build_object(
      'cash', jsonb_build_object(
        'required', v_cash_required,
        'original_movement_count', v_cash_original_count,
        'reversal_amount', v_cash_original_amount,
        'sale_total_decrement', case when coalesce(v_sale.credit_effect_status, 'not_applied') <> 'applied' then coalesce(v_sale.total, 0) else 0 end,
        'cash_component', v_sale_cash_component,
        'non_cash_component', v_sale_non_cash_component,
        'cash_session_ids', v_cash_session_ids,
        'movements', v_cash_original_movements
      ),
      'inventory', jsonb_build_object(
        'required', v_inventory_required,
        'original_movement_count', v_inventory_original_count,
        'return_quantity', v_inventory_original_quantity,
        'movements', v_inventory_original_movements
      ),
      'credit', jsonb_build_object(
        'required', v_credit_required,
        'customer_id', v_sale.customer_id,
        'customer_name', coalesce(v_customer.name, v_sale.customer_name),
        'charge_ledger_id', v_charge.id,
        'payment_ledger_id', v_payment.id,
        'debt_before', v_credit_debt_before,
        'debt_after_preview', v_credit_debt_after,
        'reversal_amount', v_credit_reversal_amount,
        'subsequent_payment_count', v_subsequent_payment_count,
        'subsequent_payments', v_subsequent_payments
      )
    ),
    'actor', jsonb_build_object('actor_key', v_actor_key, 'actor_name', v_actor_name, 'device_id', v_device_id, 'staff_user_id', v_staff_user_id),
    'mode', 'cloud_sale_cancellation_preview'
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_cash_permission(p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := private.resolve_pos_actor_type(p_context);
  v_permissions jsonb := coalesce(p_context->'actor_permissions', p_context->'staff_permissions', '{}'::jsonb);
begin
  if v_actor_type = 'admin' then return; end if;
  if v_actor_type = 'staff' and (coalesce((v_permissions->>'cash_register')::boolean, false) is true or coalesce((v_permissions->>'caja')::boolean, false) is true) then return; end if;
  raise exception 'POS_PERMISSION_DENIED:cash_register' using errcode = 'P0001';
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_cloud_customer_credit_sync_enabled(p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  perform private.assert_cloud_pos_sync_enabled(p_context);
  perform private.assert_cloud_cash_sync_enabled(p_context);

  if coalesce((p_context->'features'->>'cloud_customer_credit_sync')::boolean, false) is not true then
    raise exception 'CLOUD_CUSTOMER_CREDIT_SYNC_DISABLED' using errcode = 'P0001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_pos_permission(p_context jsonb, p_permission text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := private.resolve_pos_actor_type(p_context);
  v_permissions jsonb := coalesce(p_context->'actor_permissions', p_context->'staff_permissions', '{}'::jsonb);
begin
  if v_actor_type = 'admin' then return; end if;
  if v_actor_type = 'staff' and coalesce((v_permissions->>p_permission)::boolean, false) is true then return; end if;
  raise exception 'POS_PERMISSION_DENIED:%', p_permission using errcode = 'P0001';
end;
$function$

CREATE OR REPLACE FUNCTION private.format_pos_operational_folio_v1(p_license_id uuid, p_sequence bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_prefix text;
  v_terminal text;
  v_padding integer;
begin
  if p_license_id is null or p_sequence is null or p_sequence < 0 then
    return null;
  end if;

  select
    nullif(btrim(s.operational_prefix), ''),
    nullif(btrim(s.operational_terminal), ''),
    coalesce(s.padding, 6)
    into v_prefix, v_terminal, v_padding
    from public.pos_folio_sequences s
   where s.license_id = p_license_id
     and s.sequence_name = 'sale'
   limit 1;

  v_prefix := regexp_replace(
    upper(coalesce(v_prefix, private.derive_pos_operational_prefix_v1(p_license_id))),
    '[^A-Z0-9ÁÉÍÓÚÜÑ]',
    '',
    'g'
  );
  v_prefix := left(nullif(v_prefix, ''), 12);
  v_prefix := coalesce(v_prefix, 'LZ');

  v_terminal := regexp_replace(upper(coalesce(v_terminal, '01')), '[^A-Z0-9]', '', 'g');
  v_terminal := left(nullif(v_terminal, ''), 4);
  v_terminal := coalesce(v_terminal, '01');

  return v_prefix
    || '-'
    || lpad(v_terminal, 2, '0')
    || '-'
    || lpad(p_sequence::text, greatest(1, least(coalesce(v_padding, 6), 12)), '0');
end;
$function$

CREATE OR REPLACE FUNCTION private.insert_pos_idempotency_processing(p_license_id uuid, p_idempotency_key text, p_operation_type text, p_entity_type text, p_entity_id text, p_request_hash text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row_count integer := 0;
  v_existing_hash text;
  v_existing_status text;
begin
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) = 0 then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode = 'P0001';
  end if;

  insert into public.pos_idempotency_keys (
    license_id, idempotency_key, operation_type, entity_type,
    entity_id, request_hash, status, expires_at
  ) values (
    p_license_id, p_idempotency_key, p_operation_type, p_entity_type,
    p_entity_id, p_request_hash, 'processing', now() + interval '7 days'
  )
  on conflict (license_id, idempotency_key) do nothing;

  get diagnostics v_row_count = row_count;
  if v_row_count > 0 then return true; end if;

  select k.request_hash, k.status
  into v_existing_hash, v_existing_status
  from public.pos_idempotency_keys k
  where k.license_id = p_license_id
    and k.idempotency_key = p_idempotency_key
  for update;

  if p_request_hash is not null
     and v_existing_hash is not null
     and v_existing_hash is distinct from p_request_hash then
    raise exception 'IDEMPOTENCY_CONFLICT' using errcode = 'P0001';
  end if;

  if v_existing_hash is null and p_request_hash is not null
     and v_existing_status = 'processing' then
    update public.pos_idempotency_keys
    set request_hash = p_request_hash
    where license_id = p_license_id
      and idempotency_key = p_idempotency_key
      and request_hash is null;
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.pos_fin01_enter_pilot_v2(p_sync_contract jsonb, p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text, p_receipt_only boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_license_id uuid; v_policy private.pos_fin01_qa_pilots_v2;
begin
  perform private.pos_fin01_validate_sync_contract_v2(p_sync_contract);
  v_context:=private.validate_pos_sync_context(p_license_key,p_device_fingerprint,p_security_token,p_staff_session_token);
  v_license_id:=(v_context->>'license_id')::uuid;
  perform pg_advisory_xact_lock_shared(hashtextextended('fin01_qa_protocol:'||v_license_id::text,0));
  select * into v_policy from private.pos_fin01_qa_pilots_v2 where license_id=v_license_id for share;
  if coalesce(v_policy.protocol,1)<>2 then
    if p_receipt_only and v_policy.activated_at is not null then return; end if;
    raise exception 'CLOUD_CLIENT_UPDATE_REQUIRED' using errcode='P0001',detail='QA_PILOT_NOT_ENABLED';
  end if;
  -- Only private, authenticated entry code can create this call-scoped witness.
  -- No request parameter, claimed capability or PostgreSQL setting grants it.
  insert into private.pos_fin01_admissions_v2(transaction_id,license_id,depth)
    values(pg_current_xact_id(),v_license_id,1)
    on conflict(transaction_id,license_id) do update set depth=private.pos_fin01_admissions_v2.depth+1;
end;
$function$

CREATE OR REPLACE FUNCTION private.pos_fin01_sync_envelope_v2(p_license_id uuid, p_endpoint text, p_family text, p_context jsonb, p_payload jsonb, p_customer_id text DEFAULT NULL::text, p_cursor jsonb DEFAULT NULL::jsonb, p_operation jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_envelope jsonb;
begin
  v_envelope := jsonb_build_object(
    'contract_version', 2,
    'tenant_id', p_license_id,
    'endpoint', p_endpoint,
    'family', p_family,
    'client_identity', private.pos_fin01_client_identity_v2(p_context),
    'payload', coalesce(p_payload, '{}'::jsonb),
    -- Financial payloads contain the immutable result, including historical
    -- customer amounts. Current debt is obtained through authorized credit pulls.
    'customer_projection_scope', case when p_family = 'financial_operations' then 'OPERATION_RESULT' else 'CURRENT' end,
    'customer_projections', case when p_family = 'financial_operations' then '[]'::jsonb
      else private.pos_fin01_customer_projections_v2(p_license_id, coalesce(p_payload, '{}'::jsonb)) end
  );
  if p_customer_id is not null then
    v_envelope := v_envelope || jsonb_build_object('customer_id', p_customer_id);
  end if;
  if p_cursor is not null then
    v_envelope := v_envelope || jsonb_build_object('cursor', p_cursor);
  end if;
  if p_operation is not null then
    v_envelope := v_envelope || jsonb_build_object('operation', p_operation);
  end if;
  perform private.pos_fin01_leave_pilot_v2(p_license_id);
  return v_envelope;
end;
$function$

CREATE OR REPLACE FUNCTION private.resolve_cash_actor_key(p_context jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := private.resolve_pos_actor_type(p_context);
  v_actor_id uuid := nullif(p_context->>'actor_id', '')::uuid;
  v_staff_user_id uuid := nullif(p_context->>'staff_user_id', '')::uuid;
  v_admin_user_id uuid := nullif(p_context->>'admin_user_id', '')::uuid;
begin
  if v_actor_type = 'staff' then
    v_actor_id := coalesce(v_actor_id, v_staff_user_id);
    if v_actor_id is null then raise exception 'STAFF_USER_REQUIRED_FOR_CASH' using errcode = 'P0001'; end if;
    return 'staff:' || v_actor_id::text;
  end if;
  v_actor_id := coalesce(v_actor_id, v_admin_user_id);
  if v_actor_id is null then raise exception 'ADMIN_SESSION_REQUIRED' using errcode = 'P0001'; end if;
  return 'admin:' || v_actor_id::text;
end;
$function$

CREATE OR REPLACE FUNCTION private.resolve_cash_actor_name(p_context jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_actor_type text := private.resolve_pos_actor_type(p_context); v_name text;
begin
  if v_actor_type = 'staff' then
    v_name := nullif(btrim(coalesce(p_context->'staff_user'->>'display_name', p_context->'staff_user'->>'username', 'Staff')), '');
    return coalesce(v_name, 'Staff');
  end if;
  v_name := nullif(btrim(coalesce(p_context->'admin_user'->>'display_name', p_context->'admin_user'->>'username', 'Administrador')), '');
  return coalesce(v_name, 'Administrador');
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_customer_payment_allocations(p_allocations jsonb, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_total numeric := 0;
  v_amount numeric;
  v_result jsonb := '[]'::jsonb;
begin
  if p_allocations is null then
    return '[]'::jsonb;
  end if;

  if jsonb_typeof(p_allocations) <> 'array' then
    raise exception 'CUSTOMER_PAYMENT_ALLOCATIONS_INVALID' using errcode = 'P0001';
  end if;

  for v_item in select value from jsonb_array_elements(p_allocations)
  loop
    v_amount := coalesce((v_item->>'amount_applied')::numeric, (v_item->>'amountApplied')::numeric, 0);
    if v_amount < 0 then
      raise exception 'CUSTOMER_PAYMENT_ALLOCATION_NEGATIVE' using errcode = 'P0001';
    end if;
    if v_amount > 0 then
      v_total := v_total + v_amount;
      v_result := v_result || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'sale_id', coalesce(v_item->>'sale_id', v_item->>'saleId'),
        'amount_applied', v_amount,
        'previous_sale_balance', nullif(coalesce(v_item->>'previous_sale_balance', v_item->>'previousSaleBalance'), '')::numeric,
        'new_sale_balance', nullif(coalesce(v_item->>'new_sale_balance', v_item->>'newSaleBalance'), '')::numeric,
        'metadata', coalesce(v_item->'metadata', '{}'::jsonb)
      )));
    end if;
  end loop;

  if v_total > p_amount then
    raise exception 'CUSTOMER_PAYMENT_ALLOCATIONS_EXCEED_AMOUNT' using errcode = 'P0001';
  end if;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_pos_sync_context(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_license record;
  v_device record;
  v_features jsonb;
  v_actor_token text := nullif(btrim(coalesce(p_staff_session_token, '')), '');
  v_admin_auth jsonb := null;
  v_admin_valid boolean := false;
  v_staff_session record;
  v_staff_valid boolean := false;
  v_actor_type text;
  v_actor_id uuid;
  v_actor_session_id uuid;
  v_actor_permissions jsonb := '{}'::jsonb;
  v_staff_payload jsonb := null;
  v_admin_payload jsonb := null;
begin
  select
    l.id,
    l.license_key,
    entitlement.plan_code,
    entitlement.plan_name,
    entitlement.expires_at,
    entitlement.grace_period_ends,
    entitlement.lifecycle_state,
    entitlement.is_entitled,
    entitlement.is_in_grace,
    entitlement.effective_features
  into v_license
  from public.licenses l
  cross join lateral private.license_entitlement_state_v1(l.id) entitlement
  where l.license_key = p_license_key
  limit 1;

  if v_license.id is null then
    raise exception 'LICENSE_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_license.lifecycle_state = 'administratively_blocked' then
    raise exception 'LICENSE_NOT_ACTIVE' using errcode = 'P0001';
  end if;
  if v_license.is_entitled is not true then
    raise exception 'LICENSE_EXPIRED' using errcode = 'P0001';
  end if;

  select d.id, d.license_id, d.device_fingerprint, d.security_token,
         d.previous_security_token, d.is_active, d.device_mode,
         d.device_role as legacy_device_role,
         d.staff_user_id as legacy_staff_user_id, d.realtime_topic
  into v_device
  from public.license_devices d
  where d.license_id = v_license.id
    and d.device_fingerprint = p_device_fingerprint
  limit 1;

  if v_device.id is null then raise exception 'DEVICE_NOT_ALLOWED' using errcode = 'P0001'; end if;
  if v_device.is_active is not true then raise exception 'DEVICE_NOT_ACTIVE' using errcode = 'P0001'; end if;
  if v_device.security_token is null or nullif(p_security_token, '') is null then
    raise exception 'DEVICE_TOKEN_REQUIRED' using errcode = 'P0001';
  end if;
  if p_security_token <> v_device.security_token
     and (v_device.previous_security_token is null or p_security_token <> v_device.previous_security_token) then
    raise exception 'DEVICE_TOKEN_INVALID' using errcode = 'P0001';
  end if;
  if v_actor_token is null then raise exception 'ACTOR_SESSION_REQUIRED' using errcode = 'P0001'; end if;

  v_features := coalesce(v_license.effective_features, '{}'::jsonb);

  if v_device.device_mode in ('admin_only', 'shared') then
    v_admin_auth := private.require_active_admin_session(
      p_license_key, p_device_fingerprint, p_security_token, v_actor_token
    );
    v_admin_valid := coalesce((v_admin_auth->>'success')::boolean, false);
  end if;

  if v_device.device_mode in ('staff_only', 'shared') then
    select ss.id as session_id, ss.expires_at, s.id as staff_user_id,
           s.username, s.display_name, s.role_name, s.permissions,
           s.is_active as staff_is_active
    into v_staff_session
    from public.license_staff_sessions ss
    join public.license_staff_users s on s.id = ss.staff_user_id
    where ss.license_id = v_license.id
      and ss.device_id = v_device.id
      and s.license_id = v_license.id
      and ss.revoked_at is null
      and extensions.crypt(v_actor_token, ss.session_token_hash) = ss.session_token_hash
    order by ss.created_at desc
    limit 1;

    if v_staff_session.session_id is not null then
      if v_staff_session.expires_at <= now() then
        update public.license_staff_sessions
        set revoked_at = coalesce(revoked_at, now())
        where id = v_staff_session.session_id;
        raise exception 'STAFF_SESSION_EXPIRED' using errcode = 'P0001';
      end if;
      if v_staff_session.staff_is_active is not true then
        raise exception 'STAFF_USER_INACTIVE' using errcode = 'P0001';
      end if;
      v_staff_valid := true;
    end if;
  end if;

  if v_admin_valid and v_staff_valid then
    raise exception 'ACTOR_SESSION_AMBIGUOUS' using errcode = 'P0001';
  end if;
  if not v_admin_valid and not v_staff_valid then
    raise exception 'ACTOR_SESSION_INVALID' using errcode = 'P0001';
  end if;

  if v_admin_valid then
    v_actor_type := 'admin';
    v_actor_id := (v_admin_auth->>'admin_user_id')::uuid;
    v_actor_session_id := (v_admin_auth->>'admin_session_id')::uuid;
    v_actor_permissions := jsonb_build_object('*', true);
    v_admin_payload := v_admin_auth->'admin_user';
  else
    v_actor_type := 'staff';
    v_actor_id := v_staff_session.staff_user_id;
    v_actor_session_id := v_staff_session.session_id;
    v_actor_permissions := coalesce(v_staff_session.permissions, '{}'::jsonb);
    v_staff_payload := jsonb_build_object(
      'id', v_staff_session.staff_user_id,
      'username', v_staff_session.username,
      'display_name', v_staff_session.display_name,
      'role_name', v_staff_session.role_name,
      'permissions', v_actor_permissions
    );
    perform private.touch_license_staff_session_seen(v_staff_session.session_id, '30 seconds'::interval);
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'license_id', v_license.id,
    'license_key', v_license.license_key,
    'device_id', v_device.id,
    'device_mode', v_device.device_mode,
    'legacy_device_role', v_device.legacy_device_role,
    'actor_type', v_actor_type,
    'actor_id', v_actor_id,
    'actor_key', v_actor_type || ':' || v_actor_id::text,
    'actor_session_id', v_actor_session_id,
    'actor_permissions', v_actor_permissions,
    'device_role', v_actor_type,
    'staff_user_id', case when v_actor_type = 'staff' then v_actor_id else null end,
    'staff_permissions', case when v_actor_type = 'staff' then v_actor_permissions else '{}'::jsonb end,
    'staff_user', v_staff_payload,
    'admin_user_id', case when v_actor_type = 'admin' then v_actor_id else null end,
    'admin_session_id', case when v_actor_type = 'admin' then v_actor_session_id else null end,
    'admin_user', v_admin_payload,
    'plan_code', v_license.plan_code,
    'plan_name', v_license.plan_name,
    'features', v_features,
    'realtime_topic', v_device.realtime_topic,
    'license_lifecycle_state', v_license.lifecycle_state,
    'license_is_in_grace', v_license.is_in_grace,
    'license_expires_at', v_license.expires_at,
    'license_grace_period_ends', v_license.grace_period_ends
  ));
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_cancel_cloud_sale_apply_fase6e(p_license_key text, p_device_fingerprint text, p_security_token text DEFAULT NULL::text, p_staff_session_token text DEFAULT NULL::text, p_sale_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_staff_user_id uuid;
  v_sale_staff_user_id uuid;
  v_sale_found boolean := false;
begin
  v_context := private.validate_pos_sync_context(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token
  );
  perform private.assert_cloud_sales_cancellations_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'pos');
  perform private.assert_pos_permission(v_context, 'refunds');

  v_license_id := (v_context->>'license_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;

  select true, s.staff_user_id
  into v_sale_found, v_sale_staff_user_id
  from public.pos_sales s
  where s.license_id = v_license_id
    and s.id = nullif(btrim(coalesce(p_sale_id, '')), '')
  limit 1;

  if coalesce(v_context->>'actor_type', v_context->>'device_role', 'staff') = 'staff'
     and v_sale_found
     and v_sale_staff_user_id is distinct from v_staff_user_id
     and not private.has_pos_permission(v_context, 'sales_cancellations_global') then
    raise exception 'SALE_CANCELLATION_FORBIDDEN' using errcode = 'P0001';
  end if;

  return public.pos_cancel_cloud_sale_apply_fase6e_legacy_r1(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token,
    p_sale_id,
    p_reason,
    p_idempotency_key
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_cancel_cloud_sale_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text DEFAULT NULL::text, p_staff_session_token text DEFAULT NULL::text, p_sale_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_preview jsonb;
  v_reasons jsonb;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_first_code text;
  v_sale_id text := nullif(btrim(coalesce(p_sale_id, '')), '');
  v_actor jsonb;
begin
  v_preview := public.pos_preview_cloud_sale_cancellation(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token,
    p_sale_id,
    p_reason
  );

  v_reasons := coalesce(v_preview->'block_reasons', '[]'::jsonb);

  if v_reason is null then
    v_reasons := v_reasons || jsonb_build_array(jsonb_build_object(
      'code', 'CLOUD_SALE_CANCELLATION_REASON_REQUIRED',
      'message', 'Indica el motivo de cancelacion.'
    ));
  end if;

  if coalesce((v_preview->>'success')::boolean, false) is not true
     or coalesce((v_preview->>'can_cancel')::boolean, false) is not true
     or jsonb_array_length(v_reasons) > 0 then
    v_first_code := coalesce(v_reasons #>> '{0,code}', v_preview->>'code', 'CLOUD_SALE_CANCELLATION_BLOCKED');
    v_actor := coalesce(v_preview->'actor', '{}'::jsonb);

    if v_sale_id is not null and coalesce((v_preview->>'success')::boolean, false) is true then
      perform private.record_pos_sale_audit_event(
        ((v_preview->'sale'->>'license_id')::uuid),
        v_sale_id,
        'sale.cancel_blocked',
        nullif(v_actor->>'device_id', '')::uuid,
        nullif(v_actor->>'staff_user_id', '')::uuid,
        v_actor->>'actor_name',
        jsonb_build_object(
          'sale_id', v_sale_id,
          'folio', coalesce(v_preview->>'folio', v_preview->'sale'->>'cloud_folio', v_preview->'sale'->>'folio', v_sale_id),
          'reason', v_reason,
          'block_code', v_first_code,
          'block_reasons', v_reasons,
          'preview', v_preview->'preview',
          'idempotency_key', p_idempotency_key,
          'phase', 'fase6e1_hardening_cancelaciones_cloud'
        )
      );
    end if;

    return jsonb_build_object(
      'success', false,
      'can_cancel', false,
      'code', v_first_code,
      'message', case
        when v_first_code = 'SALE_HAS_SUBSEQUENT_CUSTOMER_PAYMENTS' then 'La venta fiada tiene abonos posteriores independientes. No se aplico ningun cambio.'
        when v_first_code = 'CLOUD_SALE_CANCELLATION_REASON_REQUIRED' then 'Indica el motivo de cancelacion.'
        else coalesce(v_preview->>'message', 'No se cancelo la venta para evitar descuadres.')
      end,
      'block_reasons', v_reasons,
      'preview', v_preview,
      'mode', 'cloud_sale_cancellation_blocked'
    );
  end if;

  return public.pos_cancel_cloud_sale_apply_fase6e(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token,
    p_sale_id,
    p_reason,
    p_idempotency_key
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_get_customer_credit_summary_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_customer_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_customer public.pos_customers;
  v_entries jsonb;
  v_total_paid numeric := 0;
  v_total_charged numeric := 0;
  v_last_payment jsonb := null;
begin
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  perform private.assert_cloud_customer_credit_sync_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'customers');
  v_license_id := (v_context->>'license_id')::uuid;

  select * into v_customer from public.pos_customers c where c.license_id = v_license_id and c.id = p_customer_id;
  if v_customer.id is null then
    return jsonb_build_object('success', false, 'code', 'CUSTOMER_NOT_FOUND', 'message', 'Cliente no encontrado.');
  end if;

  select coalesce(jsonb_agg(private.pos_customer_ledger_to_jsonb(l) order by l.created_at desc), '[]'::jsonb)
  into v_entries
  from (
    select * from public.pos_customer_ledger l
    where l.license_id = v_license_id and l.customer_id = p_customer_id and l.deleted_at is null
    order by l.created_at desc
    limit 100
  ) l;

  select coalesce(sum(case when amount < 0 then abs(amount) else 0 end), 0),
         coalesce(sum(case when amount > 0 then amount else 0 end), 0)
  into v_total_paid, v_total_charged
  from public.pos_customer_ledger l
  where l.license_id = v_license_id and l.customer_id = p_customer_id and l.deleted_at is null;

  select private.pos_customer_ledger_to_jsonb(l) into v_last_payment
  from public.pos_customer_ledger l
  where l.license_id = v_license_id and l.customer_id = p_customer_id and l.type = 'PAYMENT' and l.deleted_at is null
  order by l.created_at desc
  limit 1;

  return jsonb_build_object(
    'success', true,
    'customer', private.pos_customer_to_jsonb(v_customer),
    'debt', v_customer.debt,
    'debt_cents', v_customer.debt_cents,
    'ledger_entries', v_entries,
    'pending_credit_sales', '[]'::jsonb,
    'total_paid', v_total_paid,
    'total_charged', v_total_charged,
    'last_payment', v_last_payment
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_get_customer_credit_summary_v2(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_customer_id text DEFAULT NULL::text, p_sync_contract jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_rate jsonb;
  v_payload jsonb;
begin
  perform private.pos_fin01_enter_pilot_v2(p_sync_contract,p_license_key,p_device_fingerprint,p_security_token,p_staff_session_token);
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  v_license_id := (v_context->>'license_id')::uuid;
  perform private.assert_cloud_customer_credit_sync_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'customers');
  if nullif(btrim(p_customer_id), '') is null then raise exception 'CUSTOMER_ID_REQUIRED' using errcode = 'P0001'; end if;
  v_rate := private.pos_fin01_rate_limit_v2(p_license_key, p_device_fingerprint, p_staff_session_token,
    'pos_get_customer_credit_summary', 'POS_READ_HEAVY', 60, 600, 300, 'REPORT_RATE_LIMITED', '{}'::jsonb);
  if coalesce((v_rate->>'allowed')::boolean, false) is false then
    return private.pos_fin01_sync_envelope_v2(v_license_id, 'pos_get_customer_credit_summary_v2', 'customer_credit', v_context,
      public.build_pos_rpc_rate_limited_response(v_rate), p_customer_id);
  end if;
  v_payload := public.pos_get_customer_credit_summary_unlimited(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token, p_customer_id
  );
  v_payload := v_payload || jsonb_build_object('ledger_reconciliation_complete', false);
  return private.pos_fin01_sync_envelope_v2(v_license_id, 'pos_get_customer_credit_summary_v2', 'customer_credit', v_context,
    v_payload, p_customer_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_record_customer_payment_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_customer_id text DEFAULT NULL::text, p_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'efectivo'::text, p_cash_session_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_allocations jsonb DEFAULT '[]'::jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_staff_user_id uuid;
  v_actor_key text;
  v_actor_name text;
  v_customer public.pos_customers;
  v_customer_after public.pos_customers;
  v_session public.pos_cash_sessions;
  v_movement public.pos_cash_movements;
  v_ledger public.pos_customer_ledger;
  v_initial_ledger public.pos_customer_ledger;
  v_event public.pos_sync_events;
  v_response jsonb;
  v_idem public.pos_idempotency_keys;
  v_inserted_idem boolean;
  v_amount numeric := coalesce(p_amount, 0);
  v_payment_method text := lower(nullif(btrim(coalesce(p_payment_method, 'efectivo')), ''));
  v_is_cash boolean;
  v_current_debt numeric := 0;
  v_new_debt numeric := 0;
  v_allocations jsonb := '[]'::jsonb;
  v_initial_exists boolean := false;
begin
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  perform private.assert_cloud_customer_credit_sync_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'customers');

  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := (v_context->>'device_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;
  v_actor_key := private.resolve_cash_actor_key(v_context);
  v_actor_name := private.resolve_cash_actor_name(v_context);
  v_is_cash := v_payment_method in ('efectivo', 'cash');

  if p_customer_id is null or btrim(p_customer_id) = '' then
    raise exception 'CUSTOMER_ID_REQUIRED' using errcode = 'P0001';
  end if;
  if v_amount <= 0 then
    raise exception 'CUSTOMER_PAYMENT_AMOUNT_INVALID' using errcode = 'P0001';
  end if;
  if v_payment_method is null then
    v_payment_method := 'efectivo';
    v_is_cash := true;
  end if;
  if v_is_cash then
    perform private.assert_cash_permission(v_context);
  end if;

  v_inserted_idem := private.insert_pos_idempotency_processing(
    v_license_id,
    p_idempotency_key,
    'customer_credit.payment',
    'customer_ledger',
    null,
    null
  );

  if not v_inserted_idem then
    select * into v_idem
    from public.pos_idempotency_keys
    where license_id = v_license_id and idempotency_key = p_idempotency_key
    limit 1;

    if v_idem.status = 'completed' and v_idem.response_payload is not null then
      return v_idem.response_payload;
    end if;

    return jsonb_build_object('success', false, 'code', 'IDEMPOTENCY_PROCESSING', 'message', 'El abono ya esta en proceso.', 'idempotency_key', p_idempotency_key);
  end if;

  select * into v_customer
  from public.pos_customers c
  where c.license_id = v_license_id
    and c.id = p_customer_id
  for update;

  if v_customer.id is null then
    v_response := jsonb_build_object('success', false, 'code', 'CUSTOMER_NOT_FOUND', 'message', 'Cliente no encontrado.', 'idempotency_key', p_idempotency_key);
    perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
    return v_response;
  end if;

  if v_customer.deleted_at is not null then
    v_response := jsonb_build_object('success', false, 'code', 'CUSTOMER_DELETED', 'message', 'El cliente fue eliminado.', 'customer', private.pos_customer_to_jsonb(v_customer), 'idempotency_key', p_idempotency_key);
    perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
    return v_response;
  end if;

  select exists(
    select 1 from public.pos_customer_ledger l
    where l.license_id = v_license_id
      and l.customer_id = p_customer_id
      and l.deleted_at is null
  ) into v_initial_exists;

  if not v_initial_exists and coalesce(v_customer.debt, 0) > 0 then
    insert into public.pos_customer_ledger (
      id, license_id, customer_id, type, amount, balance_after, debt_cents_after,
      payment_method, note, reference_type, reference_id, actor_device_id,
      actor_staff_user_id, actor_name, idempotency_key, metadata
    ) values (
      'ldg_' || replace(gen_random_uuid()::text, '-', ''),
      v_license_id,
      p_customer_id,
      'INITIAL_BALANCE',
      v_customer.debt,
      v_customer.debt,
      round(v_customer.debt * 100)::integer,
      null,
      'Saldo inicial creado automaticamente al primer abono cloud.',
      'customer',
      p_customer_id,
      v_device_id,
      v_staff_user_id,
      v_actor_name,
      'customer_credit.initial_balance:auto:' || p_customer_id,
      jsonb_build_object('source', 'auto_initial_balance_before_payment')
    )
    on conflict (license_id, idempotency_key) where idempotency_key is not null do nothing
    returning * into v_initial_ledger;

    if v_initial_ledger.id is not null then
      perform private.record_pos_customer_credit_event(
        v_license_id,
        'customer_ledger',
        v_initial_ledger.id,
        'initial_balance',
        v_device_id,
        v_staff_user_id,
        v_initial_ledger.idempotency_key,
        jsonb_build_object('customer_id', p_customer_id),
        v_initial_ledger.server_version
      );
    end if;
  end if;

  select coalesce(sum(l.amount), 0)
  into v_current_debt
  from public.pos_customer_ledger l
  where l.license_id = v_license_id
    and l.customer_id = p_customer_id
    and l.deleted_at is null;

  if v_current_debt <= 0 then
    v_current_debt := coalesce(v_customer.debt, 0);
  end if;

  if v_amount > v_current_debt then
    v_response := jsonb_build_object(
      'success', false,
      'code', 'PAYMENT_EXCEEDS_DEBT',
      'message', 'El abono excede la deuda actual.',
      'current_debt', v_current_debt,
      'idempotency_key', p_idempotency_key
    );
    perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
    return v_response;
  end if;

  if v_is_cash then
    if p_cash_session_id is null or btrim(p_cash_session_id) = '' then
      select * into v_session
      from public.pos_cash_sessions s
      where s.license_id = v_license_id
        and s.actor_key = v_actor_key
        and s.status = 'open'
        and s.deleted_at is null
      order by s.opened_at desc
      limit 1
      for update;
    else
      select * into v_session
      from public.pos_cash_sessions s
      where s.license_id = v_license_id
        and s.id = p_cash_session_id
        and s.deleted_at is null
      for update;
    end if;

    if v_session.id is null then
      v_response := jsonb_build_object('success', false, 'code', 'CASH_SESSION_REQUIRED', 'message', 'Debes abrir tu caja antes de registrar abonos.', 'idempotency_key', p_idempotency_key);
      perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
      return v_response;
    end if;

    if v_session.status <> 'open' then
      v_response := jsonb_build_object('success', false, 'code', 'CASH_SESSION_CLOSED', 'message', 'La caja ya no esta abierta.', 'cash_session', private.pos_cash_session_to_jsonb(v_session), 'idempotency_key', p_idempotency_key);
      perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
      return v_response;
    end if;

    if v_session.actor_key <> v_actor_key then
      v_response := jsonb_build_object('success', false, 'code', 'CASH_SESSION_NOT_OWNED_BY_ACTOR', 'message', 'El abono debe registrarse en la caja del actor actual.', 'cash_session', private.pos_cash_session_to_jsonb(v_session), 'idempotency_key', p_idempotency_key);
      perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
      return v_response;
    end if;
  end if;

  v_allocations := private.validate_customer_payment_allocations(coalesce(p_allocations, '[]'::jsonb), v_amount);
  v_new_debt := v_current_debt - v_amount;

  insert into public.pos_customer_ledger (
    id, license_id, customer_id, type, amount, balance_after, debt_cents_after,
    payment_method, note, cash_session_id, reference_type, reference_id, sale_id,
    allocation_payload, actor_device_id, actor_staff_user_id, actor_name,
    idempotency_key, metadata
  ) values (
    'ldg_' || replace(gen_random_uuid()::text, '-', ''),
    v_license_id,
    p_customer_id,
    'PAYMENT',
    -v_amount,
    v_new_debt,
    round(v_new_debt * 100)::integer,
    v_payment_method,
    nullif(btrim(coalesce(p_note, '')), ''),
    case when v_is_cash then v_session.id else null end,
    'customer',
    p_customer_id,
    null,
    v_allocations,
    v_device_id,
    v_staff_user_id,
    v_actor_name,
    p_idempotency_key,
    jsonb_build_object('source', 'pos_record_customer_payment')
  ) returning * into v_ledger;

  v_customer_after := private.recalculate_pos_customer_debt(v_license_id, p_customer_id);

  if v_is_cash then
    insert into public.pos_cash_movements (
      id, license_id, cash_session_id, device_id, staff_user_id, actor_key,
      type, amount, concept, source, reference_type, reference_id,
      created_by_device_id, created_by_staff_user_id, actor_name, idempotency_key, metadata
    ) values (
      'mov_' || replace(gen_random_uuid()::text, '-', ''),
      v_license_id,
      v_session.id,
      v_session.device_id,
      v_session.staff_user_id,
      v_session.actor_key,
      'abono_cliente',
      v_amount,
      'Abono de cliente: ' || v_customer.name,
      'customer_payment',
      'customer_ledger',
      v_ledger.id,
      v_device_id,
      v_staff_user_id,
      v_actor_name,
      p_idempotency_key,
      jsonb_build_object('customer_id', p_customer_id, 'customer_name', v_customer.name, 'ledger_id', v_ledger.id)
    ) returning * into v_movement;

    update public.pos_customer_ledger
    set cash_movement_id = v_movement.id
    where license_id = v_license_id and id = v_ledger.id
    returning * into v_ledger;

    update public.pos_cash_sessions s
    set customer_payments_total = coalesce(s.customer_payments_total, 0) + v_amount,
        updated_at = now(),
        server_version = s.server_version + 1
    where s.license_id = v_license_id and s.id = v_session.id
    returning * into v_session;

    v_session := private.recalculate_pos_cash_session_totals(v_license_id, v_session.id, false);
  end if;

  v_event := private.record_pos_customer_credit_event(
    v_license_id,
    'customer_ledger',
    v_ledger.id,
    'payment',
    v_device_id,
    v_staff_user_id,
    p_idempotency_key,
    jsonb_build_object('customer_id', p_customer_id, 'cash_session_id', v_session.id),
    v_ledger.server_version
  );

  perform private.record_pos_customer_credit_event(
    v_license_id,
    'customer',
    p_customer_id,
    'credit_update',
    v_device_id,
    v_staff_user_id,
    p_idempotency_key,
    jsonb_build_object('customer_id', p_customer_id, 'reason', 'customer_payment'),
    v_customer_after.server_version
  );

  if v_movement.id is not null then
    perform private.record_pos_customer_credit_event(
      v_license_id,
      'cash_movement',
      v_movement.id,
      'customer_payment',
      v_device_id,
      v_staff_user_id,
      p_idempotency_key,
      jsonb_build_object('cash_session_id', v_session.id, 'actor_key', v_session.actor_key, 'movement_type', 'abono_cliente'),
      v_movement.server_version
    );

    perform private.record_pos_customer_credit_event(
      v_license_id,
      'cash_session',
      v_session.id,
      'update',
      v_device_id,
      v_staff_user_id,
      p_idempotency_key,
      jsonb_build_object('cash_session_id', v_session.id, 'reason', 'customer_payment'),
      v_session.server_version
    );
  end if;

  v_response := jsonb_build_object(
    'success', true,
    'customer', private.pos_customer_to_jsonb(v_customer_after),
    'ledger_entry', private.pos_customer_ledger_to_jsonb(v_ledger),
    'cash_movement', case when v_movement.id is null then null else private.pos_cash_movement_to_jsonb(v_movement) end,
    'cash_session', case when v_session.id is null then null else private.pos_cash_session_to_jsonb(v_session) end,
    'new_debt', v_customer_after.debt,
    'change_seq', v_event.change_seq,
    'receipt', jsonb_build_object(
      'customer_id', p_customer_id,
      'customer_name', v_customer.name,
      'amount', v_amount,
      'previous_debt', v_current_debt,
      'new_debt', v_customer_after.debt,
      'payment_method', v_payment_method,
      'cash_session_id', v_session.id,
      'ledger_id', v_ledger.id,
      'created_at', v_ledger.created_at,
      'actor_name', v_actor_name
    ),
    'idempotency_key', p_idempotency_key
  );

  perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
  return v_response;
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_record_customer_payment_v2(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_customer_id text DEFAULT NULL::text, p_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'efectivo'::text, p_cash_session_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_allocations jsonb DEFAULT '[]'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_sync_contract jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_rate jsonb;
  v_payload jsonb;
begin
  perform private.pos_fin01_enter_pilot_v2(p_sync_contract,p_license_key,p_device_fingerprint,p_security_token,p_staff_session_token);
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  v_license_id := (v_context->>'license_id')::uuid;
  perform private.assert_cloud_customer_credit_sync_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'customers');
  if nullif(btrim(p_customer_id), '') is null or nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'CUSTOMER_PAYMENT_IDENTITY_REQUIRED' using errcode = 'P0001';
  end if;
  v_rate := private.pos_fin01_rate_limit_v2(p_license_key, p_device_fingerprint, p_staff_session_token,
    'pos_record_customer_payment', 'POS_WRITE', 60, 600, 300, 'RPC_RATE_LIMITED', '{}'::jsonb);
  if coalesce((v_rate->>'allowed')::boolean, false) is false then
    return private.pos_fin01_sync_envelope_v2(v_license_id, 'pos_record_customer_payment_v2', 'customer_credit', v_context,
      public.build_pos_rpc_rate_limited_response(v_rate), p_customer_id,
      null, jsonb_build_object('idempotency_key', p_idempotency_key));
  end if;
  v_payload := public.pos_record_customer_payment_unlimited(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
    p_customer_id, p_amount, p_payment_method, p_cash_session_id, p_note,
    coalesce(p_allocations, '[]'::jsonb), p_idempotency_key
  );
  return private.pos_fin01_sync_envelope_v2(v_license_id, 'pos_record_customer_payment_v2', 'customer_credit', v_context,
    v_payload, p_customer_id, null, jsonb_build_object('idempotency_key', p_idempotency_key));
end;
$function$

