CREATE OR REPLACE FUNCTION private.derive_pos_operational_prefix_v1(p_license_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_business_name text;
  v_normalized_name text;
  v_parts text[];
begin
  if p_license_id is null then
    return 'LZ';
  end if;

  select b.business_name
    into v_business_name
    from public.business_profiles b
   where b.license_id = p_license_id
   order by b.updated_at desc nulls last, b.created_at desc nulls last, b.id
   limit 1;

  v_normalized_name := btrim(regexp_replace(
    upper(coalesce(v_business_name, '')),
    '[^A-Z0-9ÁÉÍÓÚÜÑ]+',
    ' ',
    'g'
  ));

  if v_normalized_name = '' then
    return 'LZ';
  end if;

  v_parts := regexp_split_to_array(v_normalized_name, '\s+');

  if coalesce(array_length(v_parts, 1), 0) >= 2 then
    return left(v_parts[1], 1) || left(v_parts[2], 1);
  end if;

  if length(v_parts[1]) = 1 then
    return v_parts[1] || 'X';
  end if;

  return left(v_parts[1], 2);
exception
  when others then
    return 'LZ';
end;
$function$

CREATE OR REPLACE FUNCTION private.has_pos_permission(p_context jsonb, p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := private.resolve_pos_actor_type(p_context);
  v_permissions jsonb := coalesce(p_context->'actor_permissions', p_context->'staff_permissions', '{}'::jsonb);
begin
  if v_actor_type = 'admin' then return true; end if;
  return v_actor_type = 'staff' and coalesce((v_permissions->>p_permission)::boolean, false) is true;
end;
$function$

CREATE OR REPLACE FUNCTION private.pos_fin01_customer_projections_v2(p_license_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_customer_id text;
  v_customer public.pos_customers;
  v_pending_state text;
  v_entry_status text;
  v_status text;
  v_debt_cents integer;
  v_projection_version integer;
  v_source text;
  v_result jsonb := '[]'::jsonb;
begin
  for v_customer_id in
    select customer_id from private.pos_fin01_customer_ids_v2(p_payload)
     order by customer_id collate "C"
  loop
    v_customer := null;
    v_pending_state := null;
    v_entry_status := null;
    select c.* into v_customer
      from public.pos_customers c
     where c.license_id = p_license_id and c.id = v_customer_id;

    select a.state, entry_result.status
      into v_pending_state, v_entry_status
      from private.pos_historical_credit_authorizations a
      cross join lateral jsonb_array_elements(coalesce(a.manifest->'entries', '[]'::jsonb)) entry(value)
      left join lateral (
        select result.value->>'status' as status
          from jsonb_array_elements(coalesce(a.results, '[]'::jsonb)) result(value)
         where result.value->>'customer_id' = v_customer_id
         order by result.value->>'status'
         limit 1
      ) entry_result on true
     where a.license_id = p_license_id
       and entry.value->>'customer_id' = v_customer_id
       and a.state in ('PENDING', 'CONFLICT', 'PARTIALLY_CONSUMED')
       and coalesce(entry_result.status, '') not in ('IMPORTED', 'ALREADY_IMPORTED_IDENTICAL')
     order by case a.state when 'CONFLICT' then 0 when 'PARTIALLY_CONSUMED' then 1 else 2 end
     limit 1;

    v_debt_cents := null;
    v_projection_version := greatest(coalesce(v_customer.server_version, 1), 1);
    v_source := 'pos_customers.debt_cents';
    if v_pending_state = 'CONFLICT' or v_entry_status like 'CONFLICT%' then
      v_status := 'CONFLICT';
      v_source := 'historical_credit_manifest_conflict';
    elsif v_pending_state is not null then
      v_status := 'HISTORICAL_PENDING';
      v_source := 'historical_credit_manifest_pending';
    elsif v_customer.id is null then
      v_status := 'CONFLICT';
      v_source := 'pos_customers.missing';
    elsif v_customer.debt_cents = 0 and v_customer.debt = 0 then
      v_status := 'KNOWN_ZERO';
      v_debt_cents := 0;
    elsif v_customer.debt_cents between 1 and 2147483647
       and v_customer.debt = v_customer.debt_cents::numeric / 100 then
      v_status := 'KNOWN_POSITIVE';
      v_debt_cents := v_customer.debt_cents;
    else
      v_status := 'CONFLICT';
      v_source := 'pos_customers.debt_cents_mismatch';
    end if;

    v_result := v_result || jsonb_build_array(jsonb_build_object(
      'customer_id', v_customer_id,
      'status', v_status,
      'debt_cents', v_debt_cents,
      'source', v_source,
      'projection_version', v_projection_version
    ));
  end loop;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.pos_fin01_validate_sync_contract_v2(p_sync_contract jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if jsonb_typeof(p_sync_contract) is distinct from 'object' then
    raise exception 'CLOUD_SYNC_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  if (p_sync_contract - array['contract_version', 'capabilities']) <> '{}'::jsonb
     or p_sync_contract->>'contract_version' is distinct from '2'
     or jsonb_typeof(p_sync_contract->'capabilities') is distinct from 'array' then
    raise exception 'CLOUD_SYNC_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  if not (p_sync_contract->'capabilities' @> '["historical_credit_preservation_v1","customer_projection_safe_apply_v1"]'::jsonb)
     or exists (
       select 1 from jsonb_array_elements(p_sync_contract->'capabilities') as capability(value)
        where jsonb_typeof(capability.value) is distinct from 'string'
     ) then
    raise exception 'CLOUD_SYNC_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  -- Capabilities describe client support only; all authority is checked by the
  -- existing license, device, session, actor, role, and permission validators.
end;
$function$

CREATE OR REPLACE FUNCTION private.resolve_pos_actor_type(p_context jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := nullif(p_context->>'actor_type', '');
  v_device_mode text := nullif(p_context->>'device_mode', '');
  v_legacy_role text := nullif(p_context->>'device_role', '');
begin
  if v_actor_type in ('admin', 'staff') then
    return v_actor_type;
  end if;

  if v_device_mode = 'shared' then
    raise exception 'ACTOR_SESSION_REQUIRED' using errcode = 'P0001';
  end if;

  if v_legacy_role in ('admin', 'staff') then
    return v_legacy_role;
  end if;

  raise exception 'ACTOR_SESSION_REQUIRED' using errcode = 'P0001';
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_cancel_cloud_sale_apply_fase6e_legacy_r1(p_license_key text, p_device_fingerprint text, p_security_token text DEFAULT NULL::text, p_staff_session_token text DEFAULT NULL::text, p_sale_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_staff_user_id uuid;
  v_actor_key text;
  v_actor_name text;
  v_sale_id text := nullif(btrim(coalesce(p_sale_id, '')), '');
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_idempotency_key text;
  v_inserted_idem boolean;
  v_idem public.pos_idempotency_keys;

  v_sale public.pos_sales;
  v_sale_folio text;
  v_cancellation_id text;
  v_cancellation public.pos_sale_cancellations;
  v_event public.pos_sync_events;
  v_response jsonb;
  v_latest_change_seq bigint;
  v_now timestamptz := now();

  v_cash_original record;
  v_cash_reversal public.pos_cash_movements;
  v_cash_session public.pos_cash_sessions;
  v_cash_reversal_movements jsonb := '[]'::jsonb;
  v_cash_sessions_response jsonb := '[]'::jsonb;
  v_cash_session_ids text[] := array[]::text[];
  v_cash_reversal_amount numeric := 0;
  v_sale_cash_component numeric := 0;
  v_sale_non_cash_component numeric := 0;
  v_counter_cash_delta numeric := 0;

  v_inventory_original record;
  v_inventory_reversal public.pos_inventory_movements;
  v_product public.pos_products;
  v_batch public.pos_product_batches;
  v_previous_stock numeric;
  v_new_stock numeric;
  v_previous_batch_stock numeric;
  v_new_batch_stock numeric;
  v_product_version integer;
  v_batch_version integer;
  v_sale_item_version bigint;
  v_inventory_reversal_movements jsonb := '[]'::jsonb;
  v_inventory_reversal_quantity numeric := 0;
  v_inventory_movement_idem text;

  v_customer public.pos_customers;
  v_customer_after public.pos_customers;
  v_charge public.pos_customer_ledger;
  v_payment public.pos_customer_ledger;
  v_ledger_reversal public.pos_customer_ledger;
  v_ledger_reversals jsonb := '[]'::jsonb;
  v_credit_debt_before numeric := 0;
  v_credit_running_balance numeric := 0;
  v_credit_reversal_amount numeric := 0;
  v_payment_reversal_id text;
  v_charge_reversal_id text;

  v_cash_reversal_status text := 'not_required';
  v_inventory_reversal_status text := 'not_required';
  v_credit_reversal_status text := 'not_required';
  v_reversal_status text := 'applied';
  v_customer_payload jsonb := null;

  v_permissions jsonb;
  v_requires_specific_permission boolean := false;
  v_has_specific_permission boolean := false;
  v_has_global_permission boolean := false;
begin
  if v_sale_id is null then
    return jsonb_build_object('success', false, 'code', 'SALE_ID_REQUIRED', 'message', 'La venta a cancelar es obligatoria.');
  end if;

  if v_reason is null then
    return jsonb_build_object('success', false, 'code', 'CLOUD_SALE_CANCELLATION_REASON_REQUIRED', 'message', 'Indica el motivo de cancelacion.');
  end if;

  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  perform private.assert_cloud_sales_cancellations_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'pos');

  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := (v_context->>'device_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;
  v_actor_key := private.resolve_cash_actor_key(v_context);
  v_actor_name := private.resolve_cash_actor_name(v_context);
  v_permissions := coalesce(v_context->'staff_permissions', '{}'::jsonb);

  v_idempotency_key := coalesce(nullif(btrim(p_idempotency_key), ''), 'sales.cloud_cancel:' || v_sale_id || ':' || v_device_id::text);

  select * into v_idem
  from public.pos_idempotency_keys
  where license_id = v_license_id
    and idempotency_key = v_idempotency_key
  limit 1;

  if v_idem.status = 'completed' and v_idem.response_payload is not null then
    return v_idem.response_payload;
  elsif v_idem.status = 'processing' then
    return jsonb_build_object(
      'success', false,
      'code', 'IDEMPOTENCY_PROCESSING',
      'message', 'La cancelacion ya esta en proceso. Evita presionar dos veces.',
      'idempotency_key', v_idempotency_key
    );
  end if;

  v_inserted_idem := private.insert_pos_idempotency_processing(
    v_license_id,
    v_idempotency_key,
    'sales.cloud_cancel',
    'sale',
    v_sale_id,
    md5(v_sale_id || ':' || v_reason)
  );

  if not v_inserted_idem then
    return jsonb_build_object(
      'success', false,
      'code', 'IDEMPOTENCY_PROCESSING',
      'message', 'La cancelacion ya esta en proceso. Evita presionar dos veces.',
      'idempotency_key', v_idempotency_key
    );
  end if;

  select * into v_sale
  from public.pos_sales s
  where s.license_id = v_license_id
    and s.id = v_sale_id
  for update;

  if v_sale.id is null then
    delete from public.pos_idempotency_keys where license_id = v_license_id and idempotency_key = v_idempotency_key;
    return jsonb_build_object('success', false, 'code', 'SALE_NOT_FOUND', 'message', 'Venta no encontrada.');
  end if;

  if v_sale.source_mode <> 'cloud_committed' then
    delete from public.pos_idempotency_keys where license_id = v_license_id and idempotency_key = v_idempotency_key;
    return jsonb_build_object('success', false, 'code', 'SALE_NOT_CLOUD_COMMITTED', 'message', 'Esta venta no fue confirmada en cloud.');
  end if;

  if v_sale.status = 'cancelled' or v_sale.cancelled_at is not null then
    delete from public.pos_idempotency_keys where license_id = v_license_id and idempotency_key = v_idempotency_key;
    return jsonb_build_object('success', false, 'code', 'SALE_ALREADY_CANCELLED', 'message', 'La venta ya fue cancelada anteriormente.');
  end if;

  if v_sale.status <> 'closed' then
    delete from public.pos_idempotency_keys where license_id = v_license_id and idempotency_key = v_idempotency_key;
    return jsonb_build_object('success', false, 'code', 'SALE_NOT_CLOSED', 'message', 'Solo se pueden cancelar ventas cerradas.');
  end if;

  -- Permiso especifico opcional: si el staff trae la llave, debe venir true.
  if coalesce(v_context->>'device_role', 'staff') = 'staff' then
    v_requires_specific_permission := (v_permissions ? 'sales_cancellations') or (v_permissions ? 'cancel_sales');
    v_has_specific_permission := coalesce((v_permissions->>'sales_cancellations')::boolean, false)
      or coalesce((v_permissions->>'cancel_sales')::boolean, false);
    v_has_global_permission := coalesce((v_permissions->>'reports')::boolean, false)
      or coalesce((v_permissions->>'sales_cancellations_global')::boolean, false)
      or coalesce((v_permissions->>'all_sales')::boolean, false);

    if v_requires_specific_permission and not v_has_specific_permission then
      raise exception 'POS_PERMISSION_DENIED:sales_cancellations' using errcode = 'P0001';
    end if;

    if v_sale.staff_user_id is distinct from v_staff_user_id and not v_has_global_permission then
      raise exception 'SALE_CANCELLATION_FORBIDDEN' using errcode = 'P0001';
    end if;
  end if;

  v_sale_folio := coalesce(v_sale.cloud_folio, v_sale.folio, v_sale.local_folio, v_sale.id);
  v_cancellation_id := 'cancel_' || replace(gen_random_uuid()::text, '-', '');

  v_sale_cash_component := coalesce(nullif(v_sale.metadata #>> '{payment_summary,cash_component}', '')::numeric, 0);
  v_sale_non_cash_component := coalesce(nullif(v_sale.metadata #>> '{payment_summary,non_cash_component}', '')::numeric, 0);

  perform private.record_pos_sale_audit_event(
    v_license_id,
    v_sale.id,
    'sale.cancel_requested',
    v_device_id,
    v_staff_user_id,
    v_actor_name,
    jsonb_build_object(
      'sale_id', v_sale.id,
      'folio', v_sale_folio,
      'reason', v_reason,
      'cancellation_id', v_cancellation_id,
      'idempotency_key', v_idempotency_key,
      'actor', jsonb_build_object('actor_key', v_actor_key, 'actor_name', v_actor_name, 'device_id', v_device_id, 'staff_user_id', v_staff_user_id)
    )
  );

  -- 1) Crédito/ledger: se inserta reversa de pago primero para mantener balance_after no negativo.
  if coalesce(v_sale.credit_effect_status, 'not_applied') = 'applied'
     or v_sale.credit_ledger_charge_id is not null
     or v_sale.credit_ledger_payment_id is not null then
    perform private.assert_cloud_sales_credit_enabled(v_context);
    perform private.assert_pos_permission(v_context, 'customers');

    if v_sale.customer_id is null then
      raise exception 'CREDIT_SALE_CUSTOMER_REQUIRED' using errcode = 'P0001';
    end if;

    select * into v_customer
    from public.pos_customers c
    where c.license_id = v_license_id
      and c.id = v_sale.customer_id
    for update;

    if v_customer.id is null then
      raise exception 'CUSTOMER_NOT_FOUND' using errcode = 'P0001';
    end if;

    select * into v_charge
    from public.pos_customer_ledger l
    where l.license_id = v_license_id
      and l.deleted_at is null
      and (
        (v_sale.credit_ledger_charge_id is not null and l.id = v_sale.credit_ledger_charge_id)
        or (v_sale.credit_ledger_charge_id is null and l.sale_id = v_sale.id and l.type = 'CHARGE')
      )
    order by l.created_at asc
    limit 1
    for update;

    if v_charge.id is null then
      raise exception 'CREDIT_CHARGE_LEDGER_NOT_FOUND' using errcode = 'P0001';
    end if;

    select * into v_payment
    from public.pos_customer_ledger l
    where l.license_id = v_license_id
      and l.deleted_at is null
      and (
        (v_sale.credit_ledger_payment_id is not null and l.id = v_sale.credit_ledger_payment_id)
        or (v_sale.credit_ledger_payment_id is null and l.sale_id = v_sale.id and l.type = 'PAYMENT')
      )
    order by l.created_at asc
    limit 1
    for update;

    select coalesce(sum(l.amount), 0) into v_credit_debt_before
    from public.pos_customer_ledger l
    where l.license_id = v_license_id
      and l.customer_id = v_sale.customer_id
      and l.deleted_at is null;

    v_credit_running_balance := v_credit_debt_before;

    if v_payment.id is not null and v_payment.amount < 0 then
      v_credit_running_balance := v_credit_running_balance + abs(v_payment.amount);

      insert into public.pos_customer_ledger (
        id, license_id, customer_id, type, amount, balance_after, debt_cents_after,
        payment_method, note, cash_session_id, cash_movement_id,
        reference_type, reference_id, sale_id, sale_folio, allocation_payload,
        actor_device_id, actor_staff_user_id, actor_key, actor_name,
        idempotency_key, metadata
      ) values (
        'ldg_' || replace(gen_random_uuid()::text, '-', ''),
        v_license_id,
        v_sale.customer_id,
        'CANCEL_PAYMENT',
        abs(v_payment.amount),
        v_credit_running_balance,
        round(v_credit_running_balance * 100)::integer,
        v_payment.payment_method,
        'Reversa de abono inicial por cancelacion de venta ' || v_sale_folio,
        v_payment.cash_session_id,
        null,
        'sale_cancellation',
        v_cancellation_id,
        v_sale.id,
        v_sale_folio,
        jsonb_build_array(jsonb_build_object('reversal_of', v_payment.id, 'amount', abs(v_payment.amount))),
        v_device_id,
        v_staff_user_id,
        v_actor_key,
        v_actor_name,
        v_idempotency_key || ':credit_reversal_payment',
        coalesce(v_payment.metadata, '{}'::jsonb) || jsonb_build_object(
          'reversal', true,
          'reversal_of', v_payment.id,
          'sale_cancellation_id', v_cancellation_id,
          'original_sale_id', v_sale.id,
          'phase', 'fase6e_cloud_sale_cancellations'
        )
      ) returning * into v_ledger_reversal;

      v_payment_reversal_id := v_ledger_reversal.id;
      v_ledger_reversals := v_ledger_reversals || jsonb_build_array(private.pos_customer_ledger_to_jsonb(v_ledger_reversal));
      perform private.record_pos_sync_event(v_license_id, 'customer_ledger', v_ledger_reversal.id, 'create', v_device_id, v_staff_user_id, v_ledger_reversal.idempotency_key, jsonb_build_object('sale_id', v_sale.id, 'customer_id', v_sale.customer_id, 'reversal_of', v_payment.id, 'type', 'CANCEL_PAYMENT'), v_ledger_reversal.server_version);
    end if;

    v_credit_running_balance := v_credit_running_balance - abs(v_charge.amount);
    if v_credit_running_balance < -0.005 then
      raise exception 'CUSTOMER_DEBT_NEGATIVE_AFTER_CANCEL' using errcode = 'P0001';
    end if;
    v_credit_running_balance := greatest(v_credit_running_balance, 0);

    insert into public.pos_customer_ledger (
      id, license_id, customer_id, type, amount, balance_after, debt_cents_after,
      payment_method, note, cash_session_id, cash_movement_id,
      reference_type, reference_id, sale_id, sale_folio, allocation_payload,
      actor_device_id, actor_staff_user_id, actor_key, actor_name,
      idempotency_key, metadata
    ) values (
      'ldg_' || replace(gen_random_uuid()::text, '-', ''),
      v_license_id,
      v_sale.customer_id,
      'CANCEL_CHARGE',
      -abs(v_charge.amount),
      v_credit_running_balance,
      round(v_credit_running_balance * 100)::integer,
      null,
      'Reversa de cargo por cancelacion de venta ' || v_sale_folio,
      null,
      null,
      'sale_cancellation',
      v_cancellation_id,
      v_sale.id,
      v_sale_folio,
      jsonb_build_array(jsonb_build_object('reversal_of', v_charge.id, 'amount', -abs(v_charge.amount))),
      v_device_id,
      v_staff_user_id,
      v_actor_key,
      v_actor_name,
      v_idempotency_key || ':credit_reversal_charge',
      coalesce(v_charge.metadata, '{}'::jsonb) || jsonb_build_object(
        'reversal', true,
        'reversal_of', v_charge.id,
        'sale_cancellation_id', v_cancellation_id,
        'original_sale_id', v_sale.id,
        'phase', 'fase6e_cloud_sale_cancellations'
      )
    ) returning * into v_ledger_reversal;

    v_charge_reversal_id := v_ledger_reversal.id;
    v_ledger_reversals := v_ledger_reversals || jsonb_build_array(private.pos_customer_ledger_to_jsonb(v_ledger_reversal));
    perform private.record_pos_sync_event(v_license_id, 'customer_ledger', v_ledger_reversal.id, 'create', v_device_id, v_staff_user_id, v_ledger_reversal.idempotency_key, jsonb_build_object('sale_id', v_sale.id, 'customer_id', v_sale.customer_id, 'reversal_of', v_charge.id, 'type', 'CANCEL_CHARGE'), v_ledger_reversal.server_version);

    v_customer_after := private.recalculate_pos_customer_debt(v_license_id, v_sale.customer_id);
    v_customer_payload := private.pos_customer_to_jsonb(v_customer_after);
    v_credit_reversal_amount := greatest(abs(v_charge.amount) - coalesce(abs(v_payment.amount), 0), 0);
    v_credit_reversal_status := 'applied';

    perform private.record_pos_sync_event(v_license_id, 'customer', v_sale.customer_id, 'update', v_device_id, v_staff_user_id, v_idempotency_key, jsonb_build_object('sale_id', v_sale.id, 'reason', 'sale_cancelled_credit_reversed', 'debt_before', v_credit_debt_before, 'debt_after', v_customer_after.debt), v_customer_after.server_version);

    perform private.record_pos_sale_audit_event(
      v_license_id, v_sale.id, 'sale.credit_reversed', v_device_id, v_staff_user_id, v_actor_name,
      jsonb_build_object('sale_id', v_sale.id, 'folio', v_sale_folio, 'cancellation_id', v_cancellation_id, 'charge_ledger_id', v_charge.id, 'payment_ledger_id', v_payment.id, 'charge_reversal_id', v_charge_reversal_id, 'payment_reversal_id', v_payment_reversal_id, 'debt_before', v_credit_debt_before, 'debt_after', v_customer_after.debt, 'idempotency_key', v_idempotency_key)
    );

    perform private.record_pos_sale_audit_event(
      v_license_id, v_sale.id, 'sale.customer_debt_recalculated', v_device_id, v_staff_user_id, v_actor_name,
      jsonb_build_object('sale_id', v_sale.id, 'customer_id', v_sale.customer_id, 'debt_after', v_customer_after.debt, 'cancellation_id', v_cancellation_id)
    );
  end if;

  -- 2) Inventario/lotes: devolver stock con return_in, sin borrar sale_out.
  if coalesce(v_sale.inventory_effect_status, 'not_applied') = 'applied'
     or exists (
       select 1 from public.pos_inventory_movements im
       where im.license_id = v_license_id and im.sale_id = v_sale.id and im.movement_type = 'sale_out'
     ) then
    perform private.assert_cloud_sales_inventory_enabled(v_context);

    for v_inventory_original in
      select *
      from public.pos_inventory_movements im
      where im.license_id = v_license_id
        and im.sale_id = v_sale.id
        and im.movement_type = 'sale_out'
      order by im.created_at asc, im.id asc
    loop
      v_inventory_movement_idem := v_idempotency_key || ':inventory_reversal:' || v_inventory_original.id;

      if v_inventory_original.batch_id is null then
        select * into v_product
        from public.pos_products p
        where p.license_id = v_license_id
          and p.id = v_inventory_original.product_id
          and p.deleted_at is null
        for update;

        if v_product.id is null then
          raise exception 'PRODUCT_NOT_SYNCED_FOR_CLOUD_SALE:%', v_inventory_original.product_id using errcode = 'P0001';
        end if;

        v_previous_stock := coalesce(v_product.stock, 0);
        v_new_stock := v_previous_stock + coalesce(v_inventory_original.quantity, 0);

        update public.pos_products
        set stock = v_new_stock,
            updated_at = now(),
            server_version = server_version + 1,
            updated_by_device_id = v_device_id,
            updated_by_staff_user_id = v_staff_user_id,
            last_idempotency_key = v_inventory_movement_idem,
            metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('lastInventoryCancellationId', v_cancellation_id, 'lastInventoryReturnAt', now())
        where license_id = v_license_id
          and id = v_inventory_original.product_id
        returning stock, server_version into v_new_stock, v_product_version;

        v_inventory_reversal := private.record_pos_inventory_movement(
          v_license_id,
          v_inventory_original.product_id,
          null,
          v_sale.id,
          v_inventory_original.sale_item_id,
          'return_in',
          v_inventory_original.quantity,
          v_previous_stock,
          v_new_stock,
          null,
          null,
          v_inventory_original.unit_cost,
          'Cancelacion de venta cloud ' || v_sale_folio,
          'sale_cancellation',
          v_device_id,
          v_staff_user_id,
          v_actor_key,
          v_actor_name,
          v_inventory_movement_idem,
          coalesce(v_inventory_original.metadata, '{}'::jsonb) || jsonb_build_object('reversal', true, 'reversal_of', v_inventory_original.id, 'sale_cancellation_id', v_cancellation_id, 'phase', 'fase6e_cloud_sale_cancellations')
        );

        perform private.record_pos_sync_event(v_license_id, 'product', v_inventory_original.product_id, 'update', v_device_id, v_staff_user_id, v_inventory_movement_idem, jsonb_build_object('reason', 'sale_inventory_return_in', 'sale_id', v_sale.id, 'movement_id', v_inventory_reversal.id, 'cancellation_id', v_cancellation_id), v_product_version);
      else
        select * into v_batch
        from public.pos_product_batches b
        where b.license_id = v_license_id
          and b.id = v_inventory_original.batch_id
          and b.product_id = v_inventory_original.product_id
          and b.deleted_at is null
        for update;

        if v_batch.id is null then
          raise exception 'CLOUD_BATCH_NOT_AVAILABLE:%', v_inventory_original.batch_id using errcode = 'P0001';
        end if;

        select * into v_product
        from public.pos_products p
        where p.license_id = v_license_id
          and p.id = v_inventory_original.product_id
          and p.deleted_at is null
        for update;

        if v_product.id is null then
          raise exception 'PRODUCT_NOT_SYNCED_FOR_CLOUD_SALE:%', v_inventory_original.product_id using errcode = 'P0001';
        end if;

        v_previous_stock := coalesce(v_product.stock, 0);
        v_previous_batch_stock := coalesce(v_batch.stock, 0);
        v_new_batch_stock := v_previous_batch_stock + coalesce(v_inventory_original.quantity, 0);

        update public.pos_product_batches
        set stock = v_new_batch_stock,
            updated_at = now(),
            server_version = server_version + 1,
            updated_by_device_id = v_device_id,
            updated_by_staff_user_id = v_staff_user_id,
            last_idempotency_key = v_inventory_movement_idem,
            metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('lastInventoryCancellationId', v_cancellation_id, 'lastInventoryReturnAt', now())
        where license_id = v_license_id
          and id = v_inventory_original.batch_id
        returning stock, server_version into v_new_batch_stock, v_batch_version;

        select coalesce(sum(coalesce(b.stock, 0)) filter (where b.deleted_at is null and b.is_active is true), 0)
        into v_new_stock
        from public.pos_product_batches b
        where b.license_id = v_license_id
          and b.product_id = v_inventory_original.product_id;

        update public.pos_products
        set stock = coalesce(v_new_stock, 0),
            updated_at = now(),
            server_version = server_version + 1,
            updated_by_device_id = v_device_id,
            updated_by_staff_user_id = v_staff_user_id,
            last_idempotency_key = v_inventory_movement_idem,
            metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('lastInventoryCancellationId', v_cancellation_id, 'lastInventoryReturnAt', now())
        where license_id = v_license_id
          and id = v_inventory_original.product_id
        returning stock, server_version into v_new_stock, v_product_version;

        v_inventory_reversal := private.record_pos_inventory_movement(
          v_license_id,
          v_inventory_original.product_id,
          v_inventory_original.batch_id,
          v_sale.id,
          v_inventory_original.sale_item_id,
          'return_in',
          v_inventory_original.quantity,
          v_previous_stock,
          v_new_stock,
          v_previous_batch_stock,
          v_new_batch_stock,
          v_inventory_original.unit_cost,
          'Cancelacion de venta cloud ' || v_sale_folio,
          'sale_cancellation',
          v_device_id,
          v_staff_user_id,
          v_actor_key,
          v_actor_name,
          v_inventory_movement_idem,
          coalesce(v_inventory_original.metadata, '{}'::jsonb) || jsonb_build_object('reversal', true, 'reversal_of', v_inventory_original.id, 'sale_cancellation_id', v_cancellation_id, 'phase', 'fase6e_cloud_sale_cancellations')
        );

        perform private.record_pos_sync_event(v_license_id, 'product_batch', v_inventory_original.batch_id, 'update', v_device_id, v_staff_user_id, v_inventory_movement_idem, jsonb_build_object('reason', 'sale_inventory_return_in', 'sale_id', v_sale.id, 'product_id', v_inventory_original.product_id, 'movement_id', v_inventory_reversal.id, 'cancellation_id', v_cancellation_id), v_batch_version);
        perform private.record_pos_sync_event(v_license_id, 'product', v_inventory_original.product_id, 'update', v_device_id, v_staff_user_id, v_inventory_movement_idem, jsonb_build_object('reason', 'sale_inventory_return_in', 'sale_id', v_sale.id, 'batch_id', v_inventory_original.batch_id, 'movement_id', v_inventory_reversal.id, 'cancellation_id', v_cancellation_id), v_product_version);
      end if;

      v_inventory_reversal_movements := v_inventory_reversal_movements || jsonb_build_array(private.pos_inventory_movement_to_jsonb(v_inventory_reversal));
      v_inventory_reversal_quantity := v_inventory_reversal_quantity + coalesce(v_inventory_original.quantity, 0);

      update public.pos_sale_items
      set inventory_reversal_status = 'applied',
          metadata = coalesce(metadata, '{}'::jsonb)
            || jsonb_build_object(
              'inventoryReversalStatus', 'applied',
              'inventoryReversalMovementIds', coalesce(metadata->'inventoryReversalMovementIds', '[]'::jsonb) || jsonb_build_array(v_inventory_reversal.id),
              'saleCancellationId', v_cancellation_id
            ),
          server_version = server_version + 1
      where license_id = v_license_id
        and sale_id = v_sale.id
        and id = v_inventory_original.sale_item_id
      returning server_version into v_sale_item_version;

      perform private.record_pos_sync_event(v_license_id, 'sale_item', v_inventory_original.sale_item_id, 'update', v_device_id, v_staff_user_id, v_inventory_movement_idem, jsonb_build_object('sale_id', v_sale.id, 'reason', 'inventory_reversal_applied', 'movement_id', v_inventory_reversal.id, 'cancellation_id', v_cancellation_id), coalesce(v_sale_item_version, 1)::integer);
      perform private.record_pos_sync_event(v_license_id, 'inventory_movement', v_inventory_reversal.id, 'create', v_device_id, v_staff_user_id, v_inventory_movement_idem, jsonb_build_object('sale_id', v_sale.id, 'sale_item_id', v_inventory_original.sale_item_id, 'product_id', v_inventory_original.product_id, 'batch_id', v_inventory_original.batch_id, 'cancellation_id', v_cancellation_id), v_inventory_reversal.server_version::integer);

      perform private.record_pos_sale_audit_event(v_license_id, v_sale.id, 'sale.inventory_reversed', v_device_id, v_staff_user_id, v_actor_name, jsonb_build_object('sale_id', v_sale.id, 'folio', v_sale_folio, 'cancellation_id', v_cancellation_id, 'original_movement_id', v_inventory_original.id, 'reversal_movement_id', v_inventory_reversal.id, 'product_id', v_inventory_original.product_id, 'batch_id', v_inventory_original.batch_id, 'quantity', v_inventory_original.quantity, 'idempotency_key', v_inventory_movement_idem));
    end loop;

    v_inventory_reversal_status := case when v_inventory_reversal_quantity > 0 then 'applied' else 'not_required' end;
  end if;

  -- 3) Caja: movimientos compensatorios positivos + decremento de totales oficiales del turno.
  if v_sale.cash_session_id is not null
     or exists (
       select 1 from public.pos_cash_movements cm
       where cm.license_id = v_license_id and cm.sale_id = v_sale.id and cm.deleted_at is null
     ) then
    perform private.assert_cloud_cash_sync_enabled(v_context);

    for v_cash_original in
      select *
      from public.pos_cash_movements cm
      where cm.license_id = v_license_id
        and cm.sale_id = v_sale.id
        and cm.deleted_at is null
        and cm.type in ('venta', 'venta_efectivo', 'abono_cliente')
        and cm.source not in ('sale_cancellation', 'sale_credit_cancellation')
      order by cm.created_at asc, cm.id asc
    loop
      select * into v_cash_session
      from public.pos_cash_sessions s
      where s.license_id = v_license_id
        and s.id = v_cash_original.cash_session_id
        and s.deleted_at is null
      for update;

      if v_cash_session.id is null then
        raise exception 'CASH_SESSION_NOT_FOUND' using errcode = 'P0001';
      end if;

      insert into public.pos_cash_movements (
        id, license_id, cash_session_id, device_id, staff_user_id, actor_key,
        type, amount, concept, source, reference_type, reference_id, sale_id, customer_ledger_id,
        created_by_device_id, created_by_staff_user_id, actor_name, idempotency_key, metadata
      ) values (
        'mov_' || replace(gen_random_uuid()::text, '-', ''),
        v_license_id,
        v_cash_session.id,
        v_cash_session.device_id,
        v_cash_session.staff_user_id,
        v_cash_session.actor_key,
        case when v_cash_original.type = 'abono_cliente' then 'cancelacion_abono_inicial' else 'cancelacion_venta' end,
        abs(v_cash_original.amount),
        case when v_cash_original.type = 'abono_cliente'
          then 'Cancelacion de abono inicial venta ' || v_sale_folio
          else 'Cancelacion de venta ' || v_sale_folio
        end,
        case when v_cash_original.type = 'abono_cliente' then 'sale_credit_cancellation' else 'sale_cancellation' end,
        'sale_cancellation',
        v_cancellation_id,
        v_sale.id,
        coalesce(v_payment_reversal_id, v_cash_original.customer_ledger_id),
        v_device_id,
        v_staff_user_id,
        v_actor_name,
        v_idempotency_key || ':cash_reversal:' || v_cash_original.id,
        coalesce(v_cash_original.metadata, '{}'::jsonb) || jsonb_build_object(
          'reversal', true,
          'reversal_of', v_cash_original.id,
          'sale_cancellation_id', v_cancellation_id,
          'original_sale_id', v_sale.id,
          'phase', 'fase6e_cloud_sale_cancellations',
          'amount_sign', 'cash_out_compensation'
        )
      ) returning * into v_cash_reversal;

      if v_cash_original.type = 'abono_cliente' then
        update public.pos_cash_sessions s
        set customer_payments_total = greatest(coalesce(s.customer_payments_total, 0) - abs(v_cash_original.amount), 0),
            updated_at = now(),
            server_version = s.server_version + 1,
            last_idempotency_key = v_idempotency_key
        where s.license_id = v_license_id
          and s.id = v_cash_session.id
        returning * into v_cash_session;
      else
        update public.pos_cash_sessions s
        set cash_sales_total = greatest(coalesce(s.cash_sales_total, 0) - abs(v_cash_original.amount), 0),
            updated_at = now(),
            server_version = s.server_version + 1,
            last_idempotency_key = v_idempotency_key
        where s.license_id = v_license_id
          and s.id = v_cash_session.id
        returning * into v_cash_session;
      end if;

      v_cash_session := private.recalculate_pos_cash_session_totals(v_license_id, v_cash_session.id, false);
      v_cash_reversal_amount := v_cash_reversal_amount + abs(v_cash_original.amount);
      v_cash_reversal_movements := v_cash_reversal_movements || jsonb_build_array(private.pos_cash_movement_to_jsonb(v_cash_reversal));
      v_cash_session_ids := array_append(v_cash_session_ids, v_cash_session.id);

      update public.pos_sale_payments
      set reversal_status = 'applied',
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('reversalStatus', 'applied', 'cashReversalMovementId', v_cash_reversal.id, 'saleCancellationId', v_cancellation_id),
          server_version = server_version + 1
      where license_id = v_license_id
        and sale_id = v_sale.id
        and cash_movement_id = v_cash_original.id;

      perform private.record_pos_sync_event(v_license_id, 'cash_movement', v_cash_reversal.id, 'movement', v_device_id, v_staff_user_id, v_cash_reversal.idempotency_key, jsonb_build_object('sale_id', v_sale.id, 'cash_session_id', v_cash_session.id, 'source', v_cash_reversal.source, 'cancellation_id', v_cancellation_id, 'reversal_of', v_cash_original.id), v_cash_reversal.server_version);
      perform private.record_pos_sync_event(v_license_id, 'cash_session', v_cash_session.id, 'update', v_device_id, v_staff_user_id, v_idempotency_key, jsonb_build_object('sale_id', v_sale.id, 'reason', 'sale_cancelled_cash_reversed', 'cancellation_id', v_cancellation_id), v_cash_session.server_version);

      perform private.record_pos_sale_audit_event(v_license_id, v_sale.id, 'sale.cash_reversed', v_device_id, v_staff_user_id, v_actor_name, jsonb_build_object('sale_id', v_sale.id, 'folio', v_sale_folio, 'cancellation_id', v_cancellation_id, 'original_cash_movement_id', v_cash_original.id, 'cash_reversal_movement_id', v_cash_reversal.id, 'cash_session_id', v_cash_session.id, 'amount', abs(v_cash_original.amount), 'idempotency_key', v_cash_reversal.idempotency_key));
    end loop;

    -- Ajustar ventas brutas/netas del turno para ventas no fiadas. En venta fiada 6D solo se movió customer_payments_total si hubo abono efectivo.
    if coalesce(v_sale.credit_effect_status, 'not_applied') <> 'applied' and v_sale.cash_session_id is not null then
      select * into v_cash_session
      from public.pos_cash_sessions s
      where s.license_id = v_license_id
        and s.id = v_sale.cash_session_id
        and s.deleted_at is null
      for update;

      if v_cash_session.id is not null then
        v_counter_cash_delta := case when v_cash_reversal_amount = 0 then greatest(v_sale_cash_component, 0) else 0 end;

        update public.pos_cash_sessions s
        set sales_total = greatest(coalesce(s.sales_total, 0) - coalesce(v_sale.total, 0), 0),
            sales_count = greatest(coalesce(s.sales_count, 0) - 1, 0),
            cash_sales_total = greatest(coalesce(s.cash_sales_total, 0) - v_counter_cash_delta, 0),
            non_cash_sales_total = greatest(coalesce(s.non_cash_sales_total, 0) - greatest(v_sale_non_cash_component, 0), 0),
            updated_at = now(),
            server_version = s.server_version + 1,
            last_idempotency_key = v_idempotency_key
        where s.license_id = v_license_id
          and s.id = v_cash_session.id
        returning * into v_cash_session;

        v_cash_session := private.recalculate_pos_cash_session_totals(v_license_id, v_cash_session.id, false);
        v_cash_session_ids := array_append(v_cash_session_ids, v_cash_session.id);
        perform private.record_pos_sync_event(v_license_id, 'cash_session', v_cash_session.id, 'update', v_device_id, v_staff_user_id, v_idempotency_key, jsonb_build_object('sale_id', v_sale.id, 'reason', 'sale_cancelled_sales_totals_reversed', 'cancellation_id', v_cancellation_id), v_cash_session.server_version);
      end if;
    end if;

    v_cash_reversal_status := case when v_cash_reversal_amount > 0 then 'applied' else 'not_required' end;
  end if;

  -- 4) Registrar auditoría de cancelación y marcar venta cancelada al final.
  insert into public.pos_sale_cancellations (
    id, license_id, sale_id, sale_folio, reason, status,
    cash_reversal_status, inventory_reversal_status, credit_reversal_status,
    original_total, cash_reversal_amount, inventory_reversal_quantity, credit_reversal_amount,
    actor_device_id, actor_staff_user_id, actor_key, actor_name, idempotency_key, metadata, server_version
  ) values (
    v_cancellation_id,
    v_license_id,
    v_sale.id,
    v_sale_folio,
    v_reason,
    'completed',
    v_cash_reversal_status,
    v_inventory_reversal_status,
    v_credit_reversal_status,
    coalesce(v_sale.total, 0),
    v_cash_reversal_amount,
    v_inventory_reversal_quantity,
    v_credit_reversal_amount,
    v_device_id,
    v_staff_user_id,
    v_actor_key,
    v_actor_name,
    v_idempotency_key,
    jsonb_build_object(
      'phase', 'fase6e_cloud_sale_cancellations',
      'sale_id', v_sale.id,
      'folio', v_sale_folio,
      'cash_reversal_movements', v_cash_reversal_movements,
      'inventory_reversal_movements', v_inventory_reversal_movements,
      'ledger_reversals', v_ledger_reversals,
      'credit_debt_before', v_credit_debt_before,
      'customer_after', v_customer_payload
    ),
    1
  ) returning * into v_cancellation;

  update public.pos_sales
  set status = 'cancelled',
      fulfillment_status = 'cancelled',
      cancelled_at = v_now,
      cancel_reason = v_reason,
      cancelled_by_device_id = v_device_id,
      cancelled_by_staff_user_id = v_staff_user_id,
      cancellation_id = v_cancellation_id,
      cancellation_status = 'completed',
      reversal_status = v_reversal_status,
      cash_reversal_status = v_cash_reversal_status,
      inventory_reversal_status = v_inventory_reversal_status,
      credit_reversal_status = v_credit_reversal_status,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'cloudCancellation', jsonb_build_object(
          'id', v_cancellation_id,
          'status', 'completed',
          'reason', v_reason,
          'cancelledAt', v_now,
          'cashReversalStatus', v_cash_reversal_status,
          'inventoryReversalStatus', v_inventory_reversal_status,
          'creditReversalStatus', v_credit_reversal_status,
          'cashReversalAmount', v_cash_reversal_amount,
          'inventoryReversalQuantity', v_inventory_reversal_quantity,
          'creditReversalAmount', v_credit_reversal_amount,
          'idempotencyKey', v_idempotency_key
        )
      ),
      updated_at = now(),
      server_version = server_version + 1
  where license_id = v_license_id
    and id = v_sale.id
  returning * into v_sale;

  perform private.record_pos_sale_audit_event(
    v_license_id,
    v_sale.id,
    'sale.cancelled',
    v_device_id,
    v_staff_user_id,
    v_actor_name,
    jsonb_build_object(
      'sale_id', v_sale.id,
      'folio', v_sale_folio,
      'cancellation_id', v_cancellation_id,
      'reason', v_reason,
      'cash_reversal_status', v_cash_reversal_status,
      'inventory_reversal_status', v_inventory_reversal_status,
      'credit_reversal_status', v_credit_reversal_status,
      'idempotency_key', v_idempotency_key
    )
  );

  perform private.record_pos_sync_event(v_license_id, 'sale_cancellation', v_cancellation_id, 'create', v_device_id, v_staff_user_id, v_idempotency_key, jsonb_build_object('sale_id', v_sale.id, 'folio', v_sale_folio, 'reason', v_reason), v_cancellation.server_version::integer);

  v_event := private.record_pos_sync_event(v_license_id, 'sale', v_sale.id, 'cancel', v_device_id, v_staff_user_id, v_idempotency_key, jsonb_build_object('sale_id', v_sale.id, 'folio', v_sale_folio, 'cancellation_id', v_cancellation_id, 'status', v_sale.status, 'cash_reversal_status', v_cash_reversal_status, 'inventory_reversal_status', v_inventory_reversal_status, 'credit_reversal_status', v_credit_reversal_status), v_sale.server_version::integer);

  perform private.record_pos_sync_event(v_license_id, 'report', 'overview', 'update', v_device_id, v_staff_user_id, v_idempotency_key, jsonb_build_object('reason', 'sale_cloud_cancelled', 'sale_id', v_sale.id, 'cancellation_id', v_cancellation_id), 1);

  select coalesce(jsonb_agg(private.pos_cash_session_to_jsonb(s) order by s.updated_at desc), '[]'::jsonb)
  into v_cash_sessions_response
  from public.pos_cash_sessions s
  where s.license_id = v_license_id
    and s.id = any(v_cash_session_ids);

  select coalesce(max(change_seq), 0) into v_latest_change_seq
  from public.pos_sync_events
  where license_id = v_license_id;

  v_response := jsonb_build_object(
    'success', true,
    'sale', private.pos_sale_to_jsonb(v_sale),
    'cancellation', to_jsonb(v_cancellation),
    'cash_reversal_movements', v_cash_reversal_movements,
    'cash_sessions', v_cash_sessions_response,
    'inventory_reversal_movements', v_inventory_reversal_movements,
    'ledger_reversals', v_ledger_reversals,
    'customer', v_customer_payload,
    'event', to_jsonb(v_event),
    'server_version', v_sale.server_version,
    'change_seq', v_event.change_seq,
    'latest_change_seq', v_latest_change_seq,
    'idempotency_key', v_idempotency_key,
    'mode', 'cloud_sale_cancellation'
  );

  perform private.complete_pos_idempotency(v_license_id, v_idempotency_key, v_response);
  return v_response;
exception
  when unique_violation then
    raise exception 'SALE_CANCELLATION_DUPLICATE_OR_CONFLICT' using errcode = 'P0001';
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_preview_cloud_sale_cancellation_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text DEFAULT NULL::text, p_staff_session_token text DEFAULT NULL::text, p_sale_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_staff_user_id uuid;
  v_sale_staff_user_id uuid;
  v_sale_found boolean := false;
begin
  v_context := private.validate_pos_sync_context(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token
  );
  perform private.assert_cloud_sales_cancellations_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'pos');

  if not private.has_pos_permission(v_context, 'refunds') then
    return jsonb_build_object(
      'success', false,
      'can_cancel', false,
      'code', 'POS_PERMISSION_DENIED:refunds',
      'message', 'No tienes permiso para cancelar o reembolsar ventas.',
      'block_reasons', jsonb_build_array(jsonb_build_object(
        'code', 'POS_PERMISSION_DENIED:refunds',
        'message', 'No tienes permiso para cancelar o reembolsar ventas.'
      )),
      'mode', 'cloud_sale_cancellation_preview'
    );
  end if;

  v_license_id := (v_context->>'license_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;

  select true, s.staff_user_id
  into v_sale_found, v_sale_staff_user_id
  from public.pos_sales s
  where s.license_id = v_license_id
    and s.id = nullif(btrim(coalesce(p_sale_id, '')), '')
  limit 1;

  if coalesce(v_context->>'actor_type', v_context->>'device_role', 'staff') = 'staff'
     and v_sale_found
     and v_sale_staff_user_id is distinct from v_staff_user_id
     and not private.has_pos_permission(v_context, 'sales_cancellations_global') then
    return jsonb_build_object(
      'success', false,
      'can_cancel', false,
      'code', 'SALE_CANCELLATION_FORBIDDEN',
      'message', 'No tienes permiso para cancelar esta venta.',
      'block_reasons', jsonb_build_array(jsonb_build_object(
        'code', 'SALE_CANCELLATION_FORBIDDEN',
        'message', 'No tienes permiso para cancelar esta venta.'
      )),
      'mode', 'cloud_sale_cancellation_preview'
    );
  end if;

  return public.pos_preview_cloud_sale_cancellation_legacy_r1(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token,
    p_sale_id,
    p_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_pull_customer_credit_changes_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_since_change_seq bigint DEFAULT 0, p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 1000);
  v_events jsonb;
  v_ledgers jsonb;
  v_customers jsonb;
  v_movements jsonb;
  v_sessions jsonb;
  v_latest_returned bigint;
  v_server_latest bigint;
begin
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  perform private.assert_cloud_customer_credit_sync_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'customers');
  v_license_id := (v_context->>'license_id')::uuid;

  with pulled as (
    select e.*
    from public.pos_sync_events e
    where e.license_id = v_license_id
      and e.entity_type in ('customer_ledger','customer','cash_movement','cash_session')
      and e.change_seq > coalesce(p_since_change_seq, 0)
      and (
        e.entity_type in ('customer_ledger','customer')
        or e.operation = 'customer_payment'
        or coalesce(e.metadata->>'reason', '') = 'customer_payment'
        or coalesce(e.metadata->>'movement_type', '') = 'abono_cliente'
      )
    order by e.change_seq asc
    limit v_limit
  ), ledger_ids as (
    select distinct entity_id as id from pulled where entity_type = 'customer_ledger'
  ), customer_ids as (
    select distinct coalesce(metadata->>'customer_id', entity_id) as id from pulled where entity_type in ('customer_ledger','customer')
  ), movement_ids as (
    select distinct entity_id as id from pulled where entity_type = 'cash_movement'
  ), session_ids as (
    select distinct coalesce(metadata->>'cash_session_id', case when entity_type = 'cash_session' then entity_id else null end) as id
    from pulled
    where coalesce(metadata->>'cash_session_id', case when entity_type = 'cash_session' then entity_id else null end) is not null
  )
  select
    coalesce((select jsonb_agg(to_jsonb(pulled) order by pulled.change_seq asc) from pulled), '[]'::jsonb),
    coalesce((select max(change_seq) from pulled), coalesce(p_since_change_seq, 0)),
    coalesce((select jsonb_agg(private.pos_customer_ledger_to_jsonb(l) order by l.created_at asc)
      from public.pos_customer_ledger l where l.license_id = v_license_id and l.id in (select id from ledger_ids)), '[]'::jsonb),
    coalesce((select jsonb_agg(private.pos_customer_to_jsonb(c) order by c.updated_at asc)
      from public.pos_customers c where c.license_id = v_license_id and c.id in (select id from customer_ids)), '[]'::jsonb),
    coalesce((select jsonb_agg(private.pos_cash_movement_to_jsonb(m) order by m.created_at asc)
      from public.pos_cash_movements m where m.license_id = v_license_id and m.id in (select id from movement_ids)), '[]'::jsonb),
    coalesce((select jsonb_agg(private.pos_cash_session_to_jsonb(s) order by s.updated_at asc)
      from public.pos_cash_sessions s where s.license_id = v_license_id and s.id in (select id from session_ids)), '[]'::jsonb)
  into v_events, v_latest_returned, v_ledgers, v_customers, v_movements, v_sessions;

  select coalesce(max(e.change_seq), coalesce(p_since_change_seq, 0)) into v_server_latest
  from public.pos_sync_events e
  where e.license_id = v_license_id
    and e.entity_type in ('customer_ledger','customer','cash_movement','cash_session')
    and (
      e.entity_type in ('customer_ledger','customer')
      or e.operation = 'customer_payment'
      or coalesce(e.metadata->>'reason', '') = 'customer_payment'
      or coalesce(e.metadata->>'movement_type', '') = 'abono_cliente'
    );

  return jsonb_build_object(
    'success', true,
    'events', v_events,
    'ledger_entries', v_ledgers,
    'customers', v_customers,
    'cash_movements', v_movements,
    'cash_sessions', v_sessions,
    'movements', v_movements,
    'latest_change_seq', v_latest_returned,
    'server_latest_change_seq', v_server_latest,
    'has_more', v_server_latest > v_latest_returned
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_pull_customer_credit_changes_v2(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_since_change_seq bigint DEFAULT 0, p_limit integer DEFAULT 500, p_sync_contract jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_rate jsonb;
  v_payload jsonb;
  v_since bigint := greatest(coalesce(p_since_change_seq, 0), 0);
  v_change_seq bigint;
  v_has_more boolean;
begin
  perform private.pos_fin01_enter_pilot_v2(p_sync_contract,p_license_key,p_device_fingerprint,p_security_token,p_staff_session_token);
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  v_license_id := (v_context->>'license_id')::uuid;
  perform private.assert_cloud_customer_credit_sync_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'customers');
  v_rate := private.pos_fin01_rate_limit_v2(p_license_key, p_device_fingerprint, p_staff_session_token,
    'pos_pull_customer_credit_changes', 'SYNC_PULL', 120, 600, 300, 'RPC_RATE_LIMITED', '{}'::jsonb);
  if coalesce((v_rate->>'allowed')::boolean, false) is false then
    return private.pos_fin01_sync_envelope_v2(v_license_id, 'pos_pull_customer_credit_changes_v2', 'customer_credit', v_context,
      public.build_pos_rpc_rate_limited_response(v_rate) || jsonb_build_object('latest_change_seq', v_since, 'has_more', false, 'ledger_reconciliation_complete', false),
      null, jsonb_build_object('change_seq', v_since, 'has_more', false));
  end if;
  v_payload := public.pos_pull_customer_credit_changes_unlimited(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
    v_since, least(greatest(coalesce(p_limit, 500), 1), 1000)
  );
  v_change_seq := greatest(v_since, coalesce(nullif(v_payload->>'latest_change_seq', '')::bigint, v_since));
  v_has_more := coalesce((v_payload->>'has_more')::boolean, false);
  v_payload := v_payload || jsonb_build_object('latest_change_seq', v_change_seq, 'has_more', v_has_more, 'ledger_reconciliation_complete', false);
  return private.pos_fin01_sync_envelope_v2(v_license_id, 'pos_pull_customer_credit_changes_v2', 'customer_credit', v_context,
    v_payload, null, jsonb_build_object('change_seq', v_change_seq, 'has_more', v_has_more));
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_pull_sales_changes_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text DEFAULT NULL::text, p_staff_session_token text DEFAULT NULL::text, p_since_change_seq bigint DEFAULT 0, p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_staff_user_id uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 1000);
  v_since bigint := greatest(coalesce(p_since_change_seq, 0), 0);
  v_events jsonb;
  v_sales jsonb;
  v_items jsonb;
  v_payments jsonb;
  v_latest_returned bigint;
  v_server_latest bigint;
begin
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  perform private.assert_cloud_sales_sync_base_enabled(v_context);

  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := (v_context->>'device_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;

  with visible_events as (
    select e.*,
      coalesce(e.metadata->>'sale_id', case when e.entity_type = 'sale' then e.entity_id else null end) as sale_id
    from public.pos_sync_events e
    where e.license_id = v_license_id
      and e.entity_type in ('sale','sale_item','sale_payment')
      and exists (
        select 1
        from public.pos_sales s
        where s.license_id = v_license_id
          and s.id = coalesce(e.metadata->>'sale_id', case when e.entity_type = 'sale' then e.entity_id else null end)
          and (
            coalesce(v_context->>'device_role', 'staff') <> 'staff'
            or private.has_pos_permission(v_context, 'reports')
            or s.staff_user_id = v_staff_user_id
            or s.device_id = v_device_id
          )
      )
  ), pulled as (
    select *
    from visible_events
    where change_seq > v_since
    order by change_seq asc
    limit v_limit
  ), affected_sale_ids as (
    select distinct sale_id as id from pulled where sale_id is not null
  )
  select
    coalesce((select jsonb_agg(to_jsonb(pulled) order by pulled.change_seq asc) from pulled), '[]'::jsonb),
    coalesce((select max(change_seq) from pulled), v_since),
    coalesce((select jsonb_agg(private.pos_sale_to_jsonb(s) order by s.updated_at asc, s.id asc)
      from public.pos_sales s join affected_sale_ids a on a.id = s.id where s.license_id = v_license_id), '[]'::jsonb),
    coalesce((select jsonb_agg(private.pos_sale_item_to_jsonb(i) order by i.created_at asc, i.id asc)
      from public.pos_sale_items i where i.license_id = v_license_id and i.sale_id in (select id from affected_sale_ids)), '[]'::jsonb),
    coalesce((select jsonb_agg(private.pos_sale_payment_to_jsonb(p) order by p.created_at asc, p.id asc)
      from public.pos_sale_payments p where p.license_id = v_license_id and p.sale_id in (select id from affected_sale_ids)), '[]'::jsonb)
  into v_events, v_latest_returned, v_sales, v_items, v_payments;

  with visible_events as (
    select e.change_seq,
      coalesce(e.metadata->>'sale_id', case when e.entity_type = 'sale' then e.entity_id else null end) as sale_id
    from public.pos_sync_events e
    where e.license_id = v_license_id
      and e.entity_type in ('sale','sale_item','sale_payment')
      and exists (
        select 1
        from public.pos_sales s
        where s.license_id = v_license_id
          and s.id = coalesce(e.metadata->>'sale_id', case when e.entity_type = 'sale' then e.entity_id else null end)
          and (
            coalesce(v_context->>'device_role', 'staff') <> 'staff'
            or private.has_pos_permission(v_context, 'reports')
            or s.staff_user_id = v_staff_user_id
            or s.device_id = v_device_id
          )
      )
  )
  select coalesce(max(change_seq), v_since)
  into v_server_latest
  from visible_events;

  return jsonb_build_object(
    'success', true,
    'events', v_events,
    'sales', v_sales,
    'items', v_items,
    'payments', v_payments,
    'latest_change_seq', v_latest_returned,
    'server_latest_change_seq', v_server_latest,
    'has_more', v_server_latest > v_latest_returned
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_pull_sales_snapshot_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text DEFAULT NULL::text, p_staff_session_token text DEFAULT NULL::text, p_limit integer DEFAULT 500, p_offset integer DEFAULT 0, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_include_deleted boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_staff_user_id uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 1000);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_sales jsonb;
  v_items jsonb;
  v_payments jsonb;
  v_total_count integer;
  v_latest_change_seq bigint;
begin
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  perform private.assert_cloud_sales_sync_base_enabled(v_context);

  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := (v_context->>'device_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;

  with visible_sales as (
    select s.*
    from public.pos_sales s
    where s.license_id = v_license_id
      and (p_include_deleted or s.deleted_at is null)
      and (p_date_from is null or s.sold_at >= p_date_from)
      and (p_date_to is null or s.sold_at < p_date_to)
      and (
        coalesce(v_context->>'device_role', 'staff') <> 'staff'
        or private.has_pos_permission(v_context, 'reports')
        or s.staff_user_id = v_staff_user_id
        or s.device_id = v_device_id
      )
  ), page_sales as (
    select *
    from visible_sales
    order by sold_at desc, id desc
    limit v_limit offset v_offset
  )
  select
    coalesce((select jsonb_agg(private.pos_sale_to_jsonb(s) order by s.sold_at desc, s.id desc) from page_sales s), '[]'::jsonb),
    coalesce((select jsonb_agg(private.pos_sale_item_to_jsonb(i) order by i.created_at asc, i.id asc)
      from public.pos_sale_items i where i.license_id = v_license_id and i.sale_id in (select id from page_sales)), '[]'::jsonb),
    coalesce((select jsonb_agg(private.pos_sale_payment_to_jsonb(p) order by p.created_at asc, p.id asc)
      from public.pos_sale_payments p where p.license_id = v_license_id and p.sale_id in (select id from page_sales)), '[]'::jsonb),
    (select count(*) from visible_sales)
  into v_sales, v_items, v_payments, v_total_count;

  select coalesce(max(change_seq), 0) into v_latest_change_seq
  from public.pos_sync_events
  where license_id = v_license_id
    and entity_type in ('sale','sale_item','sale_payment');

  return jsonb_build_object(
    'success', true,
    'sales', v_sales,
    'items', v_items,
    'payments', v_payments,
    'total_count', v_total_count,
    'limit', v_limit,
    'offset', v_offset,
    'latest_change_seq', v_latest_change_seq,
    'has_more', v_total_count > (v_offset + v_limit)
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.pos_sale_try_uuid(p_value text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if nullif(btrim(coalesce(p_value, '')), '') is null then
    return null;
  end if;
  return btrim(p_value)::uuid;
exception
  when invalid_text_representation then
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.pos_execute_financial_operation_core_v2(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_request_hash text DEFAULT NULL::text, p_operation_type text DEFAULT NULL::text, p_request jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '45s'
 SET lock_timeout TO '20s'
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_actor_key text;
  v_canonical jsonb;
  v_execution jsonb;
  v_cash_station_id text;
  v_cash_session_id text;
  v_session_station_id text;
  v_operation public.pos_financial_operations;
  v_response jsonb;
  v_internal_idempotency_key text;
  v_requires_cash boolean := false;
  v_layaway_id text;
  v_payment_payload jsonb;
  v_rate_limit jsonb;
  v_restaurant_order_id text;
  v_restaurant_version text;
  v_restaurant_version_at timestamptz;
  v_restaurant_order public.pos_restaurant_orders;
  v_restaurant_row_exists boolean := false;
  v_restaurant_context_supplied boolean := false;
  v_is_restaurant_settlement boolean := false;
  v_sale_total numeric;
  v_restaurant_paid_sale_id text;
  v_restaurant_paid_folio text;
  v_restaurant_close_response jsonb;
  v_restaurant_payment_summary jsonb;
begin
  perform private.enter_restaurant_financial_transition_write_v1(p_license_key,p_device_fingerprint,p_security_token,p_staff_session_token,p_request);
  v_context := private.validate_pos_sync_context(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := nullif(v_context->>'device_id', '')::uuid;
  v_actor_key := private.resolve_cash_actor_key(v_context);

  if p_operation_type in ('layaway.create', 'layaway.payment', 'layaway.cancel', 'sale.layaway_complete') then
    v_rate_limit := public.enforce_pos_rpc_rate_limit_v2(
      p_license_key, p_device_fingerprint, p_staff_session_token,
      'pos_execute_financial_operation_v1.layaway', 'POS_WRITE',
      120, 600, 300, 'RPC_RATE_LIMITED',
      jsonb_build_object('operation_type', p_operation_type)
    );
    if coalesce((v_rate_limit->>'allowed')::boolean, false) is false then
      return public.build_pos_rpc_rate_limited_response(v_rate_limit);
    end if;
  end if;

  if p_operation_type in ('layaway.create', 'layaway.payment', 'layaway.cancel', 'sale.layaway_complete') then
    perform private.assert_cloud_layaways_enabled(v_context);
    perform private.assert_pos_permission(v_context, 'pos');
  end if;

  -- Canonicalize first so restaurant settlement takes its shared lock before
  -- the cash-session row and the financial-operation ledger.
  if p_operation_type in ('sale.cashier', 'sale.cashier_inventory', 'sale.credit', 'sale.split') then
    v_canonical := private.canonical_financial_request_v1(p_operation_type, p_request);
    v_execution := private.financial_execution_request_v1(p_request);

    if p_operation_type = 'sale.split' then
      v_restaurant_order_id := nullif(btrim(v_execution->>'parent_order_id'), '');
      v_restaurant_version := nullif(btrim(v_canonical->>'parent_order_version'), '');
    else
      v_restaurant_order_id := coalesce(
        nullif(btrim(v_execution->'sale'->>'id'), ''),
        nullif(btrim(v_execution->'sale'->>'cloud_sale_id'), ''),
        nullif(btrim(v_execution->'sale'->>'cloudSaleId'), '')
      );
      if exists (
        select 1 from public.pos_restaurant_orders o
        where o.license_id = v_license_id
          and o.local_order_id = coalesce(
            nullif(btrim(v_execution->'sale'->>'local_sale_id'), ''),
            nullif(btrim(v_execution->'sale'->>'localSaleId'), '')
          )
          and o.local_order_id is distinct from v_restaurant_order_id
      ) then
        raise exception 'RESTAURANT_ORDER_CONTEXT_MISMATCH' using errcode = 'P0001';
      end if;
      v_restaurant_context_supplied := p_request ? 'restaurant_settlement';
      if v_restaurant_context_supplied then
        if v_restaurant_order_id is distinct from nullif(btrim(v_canonical #>> '{restaurant_settlement,parent_order_id}'), '') then
          raise exception 'RESTAURANT_ORDER_CONTEXT_MISMATCH' using errcode = 'P0001';
        end if;
        v_restaurant_version := nullif(btrim(v_canonical #>> '{restaurant_settlement,parent_order_version}'), '');
      end if;
    end if;

    if v_restaurant_order_id is not null then
      select exists (
        select 1 from public.pos_restaurant_orders o
         where o.license_id = v_license_id
           and o.local_order_id = v_restaurant_order_id
      ) into v_restaurant_row_exists;

      if p_operation_type = 'sale.split' or v_restaurant_context_supplied or v_restaurant_row_exists then
        v_restaurant_order := private.lock_restaurant_order_settlement_v1(v_license_id, v_restaurant_order_id);
        if v_restaurant_order.id is null then
          raise exception 'RESTAURANT_ORDER_NOT_FOUND' using errcode = 'P0001';
        end if;
        v_is_restaurant_settlement := true;
      end if;
    elsif p_operation_type = 'sale.split' or v_restaurant_context_supplied then
      raise exception 'RESTAURANT_PARENT_ORDER_REQUIRED' using errcode = 'P0001';
    end if;
  end if;

  if p_operation_type in ('sale.cashier', 'sale.cashier_inventory', 'sale.credit', 'sale.split') then
    v_cash_session_id := nullif(btrim(coalesce(p_request->>'cash_session_id', p_request->>'cashSessionId')), '');
    if v_cash_session_id is null then
      raise exception 'FINANCIAL_CASH_SESSION_ID_REQUIRED' using errcode = 'P0001';
    end if;
    v_cash_station_id := private.resolve_financial_cash_station_v1(v_license_id, v_device_id);
    select s.cash_station_id into v_session_station_id
      from public.pos_cash_sessions s
     where s.license_id = v_license_id and s.id = v_cash_session_id and s.deleted_at is null
     for update;
    if not found then
      raise exception 'CASH_SESSION_NOT_FOUND' using errcode = 'P0001';
    end if;
    if v_session_station_id is null then
      raise exception 'CASH_STATION_UNRESOLVED' using errcode = 'P0001';
    end if;
    if v_session_station_id is distinct from v_cash_station_id then
      raise exception 'CASH_SESSION_STATION_MISMATCH' using errcode = 'P0001';
    end if;
  end if;

  if p_operation_type in ('layaway.create', 'layaway.payment', 'layaway.cancel') then
    v_cash_station_id := private.resolve_financial_cash_station_v1(v_license_id, v_device_id);
    v_cash_session_id := private.layaway_request_cash_session_id_v1(p_request);
    if p_operation_type = 'layaway.payment' then
      v_requires_cash := true;
    elsif p_operation_type = 'layaway.create' then
      v_payment_payload := private.layaway_payment_payload_v1(p_request);
      v_requires_cash := coalesce(private.layaway_request_numeric_v1(v_payment_payload, array['amount', 'total'], 0), 0) > 0;
    else
      v_layaway_id := private.layaway_request_id_v1(p_request);
      v_requires_cash := not private.layaway_request_bool_v1(p_request, array['retain_money', 'retainMoney', 'retained_money'])
        and exists (
          select 1 from public.pos_layaways l
           where l.license_id = v_license_id and l.id = v_layaway_id and l.paid_amount > 0
        );
    end if;

    if v_requires_cash and v_cash_session_id is null then
      raise exception 'FINANCIAL_CASH_SESSION_ID_REQUIRED' using errcode = 'P0001';
    end if;
    if v_cash_session_id is not null then
      select s.cash_station_id into v_session_station_id
        from public.pos_cash_sessions s
       where s.license_id = v_license_id and s.id = v_cash_session_id and s.deleted_at is null
       for update;
      if not found then
        raise exception 'CASH_SESSION_NOT_FOUND' using errcode = 'P0001';
      end if;
      if v_session_station_id is null then
        raise exception 'CASH_STATION_UNRESOLVED' using errcode = 'P0001';
      end if;
      if v_session_station_id is distinct from v_cash_station_id then
        raise exception 'CASH_SESSION_STATION_MISMATCH' using errcode = 'P0001';
      end if;
      if (select status from public.pos_cash_sessions where license_id = v_license_id and id = v_cash_session_id) <> 'open' then
        raise exception 'CASH_SESSION_NOT_OPEN' using errcode = 'P0001';
      end if;
      if (select actor_key from public.pos_cash_sessions where license_id = v_license_id and id = v_cash_session_id) is distinct from v_actor_key then
        raise exception 'CASH_SESSION_FORBIDDEN' using errcode = 'P0001';
      end if;
    end if;
  end if;

  if p_operation_type in ('cash.open', 'sale.layaway_complete') then
    v_cash_station_id := private.resolve_financial_cash_station_v1(v_license_id, v_device_id);
  end if;

  if p_operation_type in ('layaway.create', 'layaway.payment', 'layaway.cancel') then
    v_canonical := private.canonical_layaway_request_v1(p_operation_type, p_request);
    v_execution := private.layaway_execution_request_v1(p_request);
  else
    v_canonical := private.canonical_financial_request_v1(p_operation_type, p_request);
    v_execution := private.financial_execution_request_v1(p_request);
  end if;

  v_operation := private.reserve_financial_operation_v1(
    v_license_id, p_idempotency_key, p_request_hash,
    p_operation_type, v_canonical, v_actor_key, v_device_id,
    v_canonical->>'cash_session_id', v_cash_station_id
  );
  if v_operation.status = 'completed' then
    return private.public_financial_response_v1(
      p_operation_type,
      v_operation.response_payload,
      p_idempotency_key,
      v_operation.legacy_idempotency_key
    );
  end if;
  v_internal_idempotency_key := v_operation.legacy_idempotency_key;

  -- Completed K/H retries returned above. Validate new attempts before sale effects.
  if v_is_restaurant_settlement then
    if v_restaurant_order.deleted_at is not null or v_restaurant_order.archived_at is not null or v_restaurant_order.checkout_closed_at is not null then
      raise exception 'RESTAURANT_ORDER_NOT_ACTIVE' using errcode = 'P0001';
    end if;
    if v_restaurant_order.status = 'cancelled' or v_restaurant_order.cancelled_at is not null then
      raise exception 'RESTAURANT_ORDER_ALREADY_CANCELLED' using errcode = 'P0001';
    end if;
    if lower(coalesce(v_restaurant_order.payment_status, 'unpaid')) = 'paid' then
      raise exception 'RESTAURANT_ORDER_ALREADY_PAID' using errcode = 'P0001';
    end if;
    if lower(coalesce(v_restaurant_order.payment_status, 'unpaid')) <> 'unpaid'
       or v_restaurant_order.status not in ('pending', 'preparing', 'ready', 'delivered')
       or v_restaurant_order.fulfillment_status not in ('pending', 'preparing', 'ready', 'delivered') then
      raise exception 'RESTAURANT_ORDER_NOT_ACTIVE' using errcode = 'P0001';
    end if;
    if v_restaurant_version is not null then
      begin
        v_restaurant_version_at := v_restaurant_version::timestamptz;
      exception
        when invalid_text_representation or datetime_field_overflow or invalid_datetime_format then
          raise exception 'RESTAURANT_ORDER_VERSION_CONFLICT' using errcode = 'P0001';
      end;
      if v_restaurant_order.updated_at is distinct from v_restaurant_version_at then
        raise exception 'RESTAURANT_ORDER_VERSION_CONFLICT' using errcode = 'P0001';
      end if;
    end if;

    if p_operation_type in ('sale.cashier', 'sale.cashier_inventory', 'sale.credit') then
      begin
        v_sale_total := nullif(v_canonical #>> '{sale,total}', '')::numeric;
      exception when invalid_text_representation or numeric_value_out_of_range then
        raise exception 'RESTAURANT_SETTLEMENT_TOTAL_MISMATCH' using errcode = 'P0001';
      end;
      if v_sale_total is null or round(v_sale_total, 2) <> round(coalesce(v_restaurant_order.total, 0), 2) then
        raise exception 'RESTAURANT_SETTLEMENT_TOTAL_MISMATCH' using errcode = 'P0001';
      end if;
    end if;
  end if;

  -- A legacy normal checkout may have committed its sale before the separate
  -- restaurant close. A new key must never settle that parent again.
  if v_is_restaurant_settlement and exists (
    select 1 from public.pos_sales s
    where s.license_id = v_license_id
      and (s.id = v_restaurant_order_id or s.local_sale_id = v_restaurant_order_id)
  ) then
    raise exception 'RESTAURANT_ORDER_SALE_RECONCILIATION_REQUIRED' using errcode = 'P0001';
  end if;

  case p_operation_type
    when 'cash.open' then
      v_response := public.pos_open_cash_session(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution, v_internal_idempotency_key
      );
    when 'cash.movement' then
      v_response := public.pos_register_cash_movement(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution->>'cash_session_id', v_execution->>'type', (v_execution->>'amount')::numeric,
        v_execution->>'concept', v_internal_idempotency_key,
        jsonb_strip_nulls(jsonb_build_object(
          'source', v_execution->>'source', 'reference_type', v_execution->>'reference_type',
          'reference_id', v_execution->>'reference_id'
        ))
      );
    when 'cash.adjust_initial_fund' then
      v_response := public.pos_adjust_initial_cash_fund(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution->>'cash_session_id', (v_execution->>'new_opening_amount')::numeric,
        v_execution->>'reason', (v_execution->>'expected_version')::integer,
        v_internal_idempotency_key
      );
    when 'cash.close' then
      v_response := public.pos_close_cash_session(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution->>'cash_session_id', v_execution, (v_execution->>'expected_version')::integer,
        v_internal_idempotency_key
      );
    when 'cash.admin_close' then
      v_response := public.pos_admin_close_cash_session(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution->>'cash_session_id', v_execution->>'closing_mode',
        (v_execution->>'counted_amount')::numeric, (v_execution->>'next_shift_fund')::numeric,
        v_execution->>'reason_code', v_execution->>'comments',
        (v_execution->>'expected_version')::integer, v_internal_idempotency_key
      );
    when 'sale.cashier' then
      v_response := public.pos_create_cloud_sale_cashier(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution->'sale', v_execution->'items', v_execution->'payments',
        v_execution->>'cash_session_id', v_internal_idempotency_key
      );
    when 'sale.cashier_inventory' then
      v_response := public.pos_create_cloud_sale_cashier_inventory(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution->'sale', v_execution->'items', v_execution->'payments',
        v_execution->>'cash_session_id', v_internal_idempotency_key
      );
    when 'sale.credit' then
      v_response := private.pos_fin01_create_credit_rate_limited_v2(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution->'sale', v_execution->'items', v_execution->'payments',
        v_execution->>'cash_session_id', v_execution->>'customer_id', v_internal_idempotency_key
      );
    when 'sale.split' then
      v_response := private.execute_split_sale_financial_v1(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution, v_internal_idempotency_key
      );
    when 'sale.layaway_complete' then
      v_response := private.execute_layaway_completion_financial_v1(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution, p_idempotency_key
      );
    when 'sale.cancel' then
      v_response := private.pos_fin01_cancel_sale_rate_limited_v2(
        p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
        v_execution->>'sale_id', v_execution->>'reason', v_internal_idempotency_key
      );
    when 'layaway.create' then
      v_response := private.execute_layaway_create_financial_v1(
        v_context, v_execution, p_idempotency_key, p_request_hash, v_cash_station_id
      );
    when 'layaway.payment' then
      v_response := private.execute_layaway_payment_financial_v1(
        v_context, v_execution, p_idempotency_key, p_request_hash, v_cash_station_id
      );
    when 'layaway.cancel' then
      v_response := private.execute_layaway_cancel_financial_v1(
        v_context, v_execution, p_idempotency_key, p_request_hash, v_cash_station_id
      );
    else
      raise exception 'FINANCIAL_OPERATION_TYPE_UNSUPPORTED' using errcode = 'P0001';
  end case;

  if v_is_restaurant_settlement and p_operation_type in ('sale.cashier', 'sale.cashier_inventory', 'sale.credit') then
    if coalesce((v_response->>'success')::boolean, false) is not true then
      raise exception 'RESTAURANT_SETTLEMENT_SALE_NOT_CONFIRMED:%',
        coalesce(v_response->>'code', 'UNKNOWN') using errcode = 'P0001';
    end if;
    v_restaurant_paid_sale_id := nullif(btrim(coalesce(v_response->'sale'->>'id', v_response->'sale'->>'cloud_sale_id', v_response->'sale'->>'cloudSaleId')), '');
    v_restaurant_paid_folio := nullif(btrim(coalesce(v_response->'sale'->>'pos_folio', v_response->'sale'->>'folio')), '');
    if v_restaurant_paid_sale_id is null then
      raise exception 'RESTAURANT_SETTLEMENT_SALE_RESPONSE_INVALID' using errcode = 'P0001';
    end if;
    v_restaurant_payment_summary := jsonb_build_object('source', 'restaurant_normal_checkout', 'operation_type', p_operation_type, 'payment_method', v_canonical #>> '{sale,payment_method}', 'total', round(v_sale_total, 2), 'sourceMode', 'cloud_committed');
    v_restaurant_close_response := public.pos_close_restaurant_order_after_checkout_unlimited(
      p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
      v_restaurant_order_id, v_restaurant_paid_sale_id, v_restaurant_paid_folio,
      round(v_sale_total, 2), v_restaurant_payment_summary, v_internal_idempotency_key || ':restaurant-close'
    );
    if coalesce((v_restaurant_close_response->>'success')::boolean, false) is not true or coalesce((v_restaurant_close_response->>'found')::boolean, false) is not true then
      raise exception 'RESTAURANT_ORDER_CLOSE_NOT_CONFIRMED:%', coalesce(v_restaurant_close_response->>'code', 'UNKNOWN') using errcode = 'P0001';
    end if;
    v_response := v_response || jsonb_build_object('restaurant_settlement', jsonb_build_object('success', true, 'parent_order_id', v_restaurant_order_id, 'payment_status', 'paid', 'paid_sale_id', v_restaurant_paid_sale_id, 'paid_sale_folio', v_restaurant_paid_folio, 'total', round(v_sale_total, 2), 'status', v_restaurant_close_response #>> '{order,status}', 'fulfillment_status', v_restaurant_close_response #>> '{order,fulfillment_status}'));
  end if;

  v_response := private.public_financial_response_v1(
    p_operation_type, v_response, p_idempotency_key, v_internal_idempotency_key
  );
  perform private.complete_financial_operation_v1(v_license_id, p_idempotency_key, v_response);
  return v_response;
end;
$function$

CREATE OR REPLACE FUNCTION private.pos_fin01_cancel_sale_rate_limited_v2(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text, p_sale_id text, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rate jsonb;
begin
  v_rate := public.enforce_pos_rpc_rate_limit_v2(
    p_license_key, p_device_fingerprint, p_staff_session_token,
    'pos_cancel_cloud_sale', 'POS_WRITE', 60, 600, 300,
    'RPC_RATE_LIMITED', '{}'::jsonb
  );
  if coalesce((v_rate->>'allowed')::boolean, false) is false then
    return public.build_pos_rpc_rate_limited_response(v_rate);
  end if;
  return public.pos_cancel_cloud_sale_unlimited(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
    p_sale_id, p_reason, p_idempotency_key
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pos_execute_financial_operation_v2(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_request_hash text DEFAULT NULL::text, p_operation_type text DEFAULT NULL::text, p_request jsonb DEFAULT '{}'::jsonb, p_sync_contract jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '45s'
 SET lock_timeout TO '20s'
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_payload jsonb;
  v_operation public.pos_financial_operations;
  v_customer_id text;
begin
  perform private.pos_fin01_enter_pilot_v2(p_sync_contract,p_license_key,p_device_fingerprint,p_security_token,p_staff_session_token);
  if not (p_sync_contract->'capabilities' @> '["financial_operation_result_v1"]'::jsonb) then
    raise exception 'CLOUD_CLIENT_UPDATE_REQUIRED' using errcode = 'P0001';
  end if;
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  v_license_id := (v_context->>'license_id')::uuid;
  v_payload := private.pos_execute_financial_operation_core_v2(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token,
    p_idempotency_key, p_request_hash, p_operation_type, coalesce(p_request, '{}'::jsonb)
  );
  select o.* into v_operation
    from public.pos_financial_operations o
   where o.license_id = v_license_id and o.idempotency_key = p_idempotency_key;
  v_customer_id := nullif(btrim(coalesce(p_request->>'customer_id', p_request #>> '{sale,customer_id}', p_request #>> '{sale,customerId}')), '');
  return private.pos_fin01_sync_envelope_v2(v_license_id, 'pos_execute_financial_operation_v2', 'financial_operations', v_context,
    v_payload, v_customer_id, null,
    jsonb_build_object('idempotency_key', p_idempotency_key, 'request_hash', p_request_hash,
      'operation_type', coalesce(v_operation.operation_type, p_operation_type),
      'status', coalesce(v_operation.status, 'unknown'), 'operation_id', v_operation.id));
end;
$function$

CREATE OR REPLACE FUNCTION private.canonical_financial_request_v1(p_operation_type text, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_request jsonb := coalesce(p_request, '{}'::jsonb);
  v_split_intent text;
  v_split_child_count integer;
  v_split_payer_count integer;
  v_split_payer jsonb;
  v_split_child jsonb;
  v_parent_order_version text;
  v_parent_order_version_at timestamptz;
  v_credit_payer_count integer := 0;
  v_credit_customer_id text;
  v_payer_customer_id text;
  v_customer_id_snake text;
  v_customer_id_camel text;
  v_child_customer_id text;
  v_child_sale_customer_id text;
begin
  if jsonb_typeof(v_request) <> 'object' then
    raise exception 'FINANCIAL_REQUEST_CONTRACT_INVALID' using errcode = 'P0001';
  end if;

  case p_operation_type
    when 'cash.open' then
      return jsonb_build_object('opening', jsonb_build_object(
        'opening_amount', coalesce(private.financial_decimal_v1(private.financial_first_nonblank_scalar_v1(v_request,array['opening_amount','montoInicial'])),'0'),
        'opening_counted_amount', private.financial_decimal_v1(private.financial_first_nonblank_scalar_v1(v_request,array['opening_counted_amount','montoContado','montoContadoInicial'])),
        'opening_suggested_amount', private.financial_decimal_v1(private.financial_first_nonblank_scalar_v1(v_request,array['opening_suggested_amount','montoSugerido'])),
        'opening_policy', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request,array['opening_policy','politicaApertura'])),
        'opening_origin', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request,array['opening_origin','origen'])),
        'is_auto_opening', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request,array['is_auto_opening','esAutoApertura'])),
        'responsible_name', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request,array['responsible_name','responsable']))
      ));
    when 'cash.movement' then
      return jsonb_build_object(
        'cash_session_id', v_request->>'cash_session_id',
        'type', v_request->>'type',
        'amount', private.financial_decimal_v1(v_request->'amount'),
        'concept', v_request->>'concept',
        'source', v_request->>'source',
        'reference_type', v_request->>'reference_type',
        'reference_id', v_request->>'reference_id'
      );
    when 'cash.adjust_initial_fund' then
      return jsonb_build_object(
        'cash_session_id', v_request->>'cash_session_id',
        'new_opening_amount', private.financial_decimal_v1(v_request->'new_opening_amount'),
        'reason', v_request->>'reason',
        'expected_version', private.financial_integer_v1(v_request->'expected_version')
      );
    when 'cash.close' then
      return jsonb_build_object(
        'cash_session_id', v_request->>'cash_session_id',
        'closing_counted_amount', private.financial_decimal_v1(private.financial_first_nonblank_scalar_v1(v_request,array['closing_counted_amount','countedAmount','montoFisicoTotal'])),
        'next_shift_fund', private.financial_decimal_v1(private.financial_first_nonblank_scalar_v1(v_request,array['next_shift_fund','nextShiftFund','montoFondoSiguienteTurno'])),
        'comments', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request,array['audit_comments','comments','comentarios'])),
        'expected_version', private.financial_integer_v1(v_request->'expected_version')
      );
    when 'cash.admin_close' then
      return jsonb_build_object(
        'cash_session_id', v_request->>'cash_session_id',
        'closing_mode', v_request->>'closing_mode',
        'counted_amount', private.financial_decimal_v1(v_request->'counted_amount'),
        'next_shift_fund', private.financial_decimal_v1(v_request->'next_shift_fund'),
        'reason_code', v_request->>'reason_code',
        'comments', v_request->>'comments',
        'expected_version', private.financial_integer_v1(v_request->'expected_version')
      );
    when 'sale.cashier', 'sale.cashier_inventory', 'sale.credit' then
      if jsonb_typeof(v_request->'sale') <> 'object'
         or jsonb_typeof(v_request->'items') <> 'array'
         or jsonb_typeof(v_request->'payments') <> 'array' then
        raise exception 'FINANCIAL_SALE_CONTRACT_INVALID' using errcode = 'P0001';
      end if;
      return jsonb_build_object(
        'sale', private.canonical_financial_sale_v1(p_operation_type, v_request->'sale'),
        'items', (
          select coalesce(jsonb_agg(private.canonical_financial_sale_item_v1(value) order by ordinality), '[]'::jsonb)
          from jsonb_array_elements(v_request->'items') with ordinality
        ),
        'payments', (
          select coalesce(jsonb_agg(private.canonical_financial_payment_v1(p_operation_type, value) order by ordinality), '[]'::jsonb)
          from jsonb_array_elements(v_request->'payments') with ordinality
        ),
        'cash_session_id', private.financial_text_v1(v_request->'cash_session_id'),
        'customer_id', private.financial_text_v1(v_request->'customer_id')
      ) || private.canonical_restaurant_settlement_v1(v_request);
    when 'sale.split' then
      v_split_intent := coalesce(
        private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request, array['split_intent','splitIntent'])),
        'by_items'
      );
      if v_split_intent not in ('by_items', 'equal_payment', 'custom_payment')
         or jsonb_typeof(v_request->'children') <> 'array' then
        raise exception 'FINANCIAL_SPLIT_CONTRACT_INVALID' using errcode = 'P0001';
      end if;
      v_split_child_count := jsonb_array_length(coalesce(v_request->'children', '[]'::jsonb));
      if (v_split_intent = 'by_items' and (v_split_child_count < 2 or v_split_child_count > 8))
         or (v_split_intent in ('equal_payment', 'custom_payment') and v_split_child_count <> 1) then
        raise exception 'FINANCIAL_SPLIT_CONTRACT_INVALID' using errcode = 'P0001';
      end if;
      v_parent_order_version := nullif(btrim(private.financial_text_v1(
        private.financial_first_nonblank_scalar_v1(v_request, array['parent_order_version','parentOrderVersion'])
      )), '');
      if v_split_intent in ('equal_payment', 'custom_payment') then
        if jsonb_typeof(coalesce(v_request->'split_payers', v_request->'splitPayers')) <> 'array' then
          raise exception 'FINANCIAL_SPLIT_PAYER_CONTRACT_INVALID' using errcode = 'P0001';
        end if;
        v_split_payer_count := jsonb_array_length(coalesce(v_request->'split_payers', v_request->'splitPayers'));
        if v_split_payer_count < 2 or v_split_payer_count > 8 then
          raise exception 'FINANCIAL_SPLIT_PAYER_CONTRACT_INVALID' using errcode = 'P0001';
        end if;
        if v_parent_order_version is null
           or v_parent_order_version !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?([zZ]|[+-][0-9]{2}:[0-9]{2})$' then
          raise exception 'RESTAURANT_ORDER_VERSION_CONFLICT' using errcode = 'P0001';
        end if;
        begin
          v_parent_order_version_at := v_parent_order_version::timestamptz;
        exception
          when invalid_text_representation or datetime_field_overflow or invalid_datetime_format then
            raise exception 'RESTAURANT_ORDER_VERSION_CONFLICT' using errcode = 'P0001';
        end;

        for v_split_payer in
          select value
            from jsonb_array_elements(coalesce(v_request->'split_payers', v_request->'splitPayers', '[]'::jsonb))
        loop
          if private.financial_payment_method_v1(
               'sale.credit',
               private.financial_text_v1(private.financial_first_nonblank_scalar_v1(
                 v_split_payer, array['payment_method','paymentMethod','method']
               ))
             ) in ('credit', 'mixed_credit') then
            v_customer_id_snake := nullif(btrim(v_split_payer->>'customer_id'), '');
            v_customer_id_camel := nullif(btrim(v_split_payer->>'customerId'), '');
            if v_customer_id_snake is not null
               and v_customer_id_camel is not null
               and v_customer_id_snake <> v_customer_id_camel then
              raise exception 'FINANCIAL_SPLIT_CREDIT_CUSTOMER_MISMATCH' using errcode = 'P0001';
            end if;
            v_payer_customer_id := coalesce(v_customer_id_snake, v_customer_id_camel);
            if v_payer_customer_id is null then
              raise exception 'FINANCIAL_SPLIT_CREDIT_PAYER_INVALID' using errcode = 'P0001';
            end if;
            v_credit_payer_count := v_credit_payer_count + 1;
            if v_credit_payer_count = 1 then
              v_credit_customer_id := v_payer_customer_id;
            end if;
          end if;
        end loop;

        if v_credit_payer_count > 1 then
          raise exception 'FINANCIAL_SPLIT_CREDIT_PAYER_INVALID' using errcode = 'P0001';
        end if;

        if v_credit_payer_count = 1 then
          for v_split_child in
            select value
              from jsonb_array_elements(coalesce(v_request->'children', '[]'::jsonb))
          loop
            v_customer_id_snake := nullif(btrim(v_split_child->>'customer_id'), '');
            v_customer_id_camel := nullif(btrim(v_split_child->>'customerId'), '');
            if v_customer_id_snake is not null
               and v_customer_id_camel is not null
               and v_customer_id_snake <> v_customer_id_camel then
              raise exception 'FINANCIAL_SPLIT_CREDIT_CUSTOMER_MISMATCH' using errcode = 'P0001';
            end if;
            v_child_customer_id := coalesce(v_customer_id_snake, v_customer_id_camel);

            v_customer_id_snake := nullif(btrim(v_split_child->'sale'->>'customer_id'), '');
            v_customer_id_camel := nullif(btrim(v_split_child->'sale'->>'customerId'), '');
            if v_customer_id_snake is not null
               and v_customer_id_camel is not null
               and v_customer_id_snake <> v_customer_id_camel then
              raise exception 'FINANCIAL_SPLIT_CREDIT_CUSTOMER_MISMATCH' using errcode = 'P0001';
            end if;
            v_child_sale_customer_id := coalesce(v_customer_id_snake, v_customer_id_camel);

            if (v_child_customer_id is not null and v_child_customer_id <> v_credit_customer_id)
               or (v_child_sale_customer_id is not null and v_child_sale_customer_id <> v_credit_customer_id) then
              raise exception 'FINANCIAL_SPLIT_CREDIT_CUSTOMER_MISMATCH' using errcode = 'P0001';
            end if;
          end loop;
        end if;
      end if;
      return jsonb_build_object(
        'parent_order_id', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request, array['parent_order_id','parentOrderId'])),
        'parent_order_version', case
          when v_split_intent in ('equal_payment', 'custom_payment') then v_parent_order_version
          else private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request, array['parent_order_version','parentOrderVersion']))
        end,
        'split_group_id', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request, array['split_group_id','splitGroupId'])),
        'cash_session_id', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request, array['cash_session_id','cashSessionId'])),
        'children', (
          select coalesce(jsonb_agg(
            jsonb_build_object(
              'label', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(value, array['label'])),
              'sale', private.canonical_financial_sale_v1(
                case
                  when private.financial_payment_method_v1(
                    'sale.credit',
                    lower(coalesce(value->'sale'->>'payment_method', value->'sale'->>'paymentMethod', ''))
                  ) in ('credit','mixed_credit')
                    then 'sale.credit'
                  when coalesce((value->'sale'->'metadata'->>'cloudInventoryEffects')::boolean, false)
                    then 'sale.cashier_inventory'
                  else 'sale.cashier'
                end,
                value->'sale'
              ) ||
                case
                  when v_split_intent in ('equal_payment', 'custom_payment') and v_credit_payer_count = 1
                    then jsonb_build_object('customer_id', v_credit_customer_id)
                  else '{}'::jsonb
                end,
              'items', (
                select coalesce(jsonb_agg(private.canonical_financial_sale_item_v1(item_value) order by item_ordinality), '[]'::jsonb)
                from jsonb_array_elements(coalesce(value->'items', '[]'::jsonb)) with ordinality as item_rows(item_value, item_ordinality)
              ),
              'payments', (
                select coalesce(jsonb_agg(
                  private.canonical_financial_payment_v1(
                    case
                      when private.financial_payment_method_v1(
                        'sale.credit',
                        lower(coalesce(value->'sale'->>'payment_method', value->'sale'->>'paymentMethod', ''))
                      ) in ('credit','mixed_credit')
                        then 'sale.credit'
                      when coalesce((value->'sale'->'metadata'->>'cloudInventoryEffects')::boolean, false)
                        then 'sale.cashier_inventory'
                      else 'sale.cashier'
                    end,
                    payment_value
                  ) order by payment_ordinality
                ), '[]'::jsonb)
                from jsonb_array_elements(coalesce(value->'payments', '[]'::jsonb)) with ordinality as payment_rows(payment_value, payment_ordinality)
              ),
              'customer_id', private.financial_text_v1(
                to_jsonb(
                  case
                    when v_split_intent in ('equal_payment', 'custom_payment') then coalesce(
                      nullif(btrim(value->>'customer_id'), ''),
                      nullif(btrim(value->>'customerId'), ''),
                      nullif(btrim(value->'sale'->>'customer_id'), ''),
                      nullif(btrim(value->'sale'->>'customerId'), ''),
                      case when v_credit_payer_count = 1 then v_credit_customer_id else null end
                    )
                    else coalesce(
                      nullif(btrim(value->>'customer_id'), ''),
                      nullif(btrim(value->'sale'->>'customer_id'), ''),
                      nullif(btrim(value->'sale'->>'customerId'), '')
                    )
                  end
                )
              )
            ) order by ordinality
          ), '[]'::jsonb)
          from jsonb_array_elements(v_request->'children') with ordinality
        )
      ) || case
        when v_split_intent in ('equal_payment', 'custom_payment') then jsonb_build_object(
          'split_intent', v_split_intent,
          'split_payers', (
            select coalesce(jsonb_agg(private.canonical_financial_split_payer_v1(value) order by ordinality), '[]'::jsonb)
            from jsonb_array_elements(coalesce(v_request->'split_payers', v_request->'splitPayers', '[]'::jsonb)) with ordinality
          )
        )
        else '{}'::jsonb
      end;
    when 'sale.layaway_complete' then
      if jsonb_typeof(v_request->'sale') <> 'object'
         or jsonb_typeof(v_request->'items') <> 'array'
         or jsonb_typeof(v_request->'payments') <> 'array' then
        raise exception 'FINANCIAL_LAYAWAY_CONTRACT_INVALID' using errcode = 'P0001';
      end if;
      return jsonb_build_object(
        'layaway_id', private.financial_text_v1(private.financial_first_nonblank_scalar_v1(v_request, array['layaway_id','layawayId'])),
        'sale', private.canonical_financial_sale_v1('sale.layaway_complete', v_request->'sale'),
        'items', (
          select coalesce(jsonb_agg(private.canonical_financial_sale_item_v1(value) order by ordinality), '[]'::jsonb)
          from jsonb_array_elements(v_request->'items') with ordinality
        ),
        'payments', (
          select coalesce(jsonb_agg(private.canonical_financial_payment_v1('sale.layaway_complete', value) order by ordinality), '[]'::jsonb)
          from jsonb_array_elements(v_request->'payments') with ordinality
        )
      );
    when 'sale.cancel' then
      return jsonb_build_object('sale_id', v_request->>'sale_id', 'reason', v_request->>'reason');
    else
      raise exception 'FINANCIAL_OPERATION_TYPE_UNSUPPORTED' using errcode = 'P0001';
  end case;
end;
$function$

CREATE OR REPLACE FUNCTION private.complete_financial_operation_v1(p_license_id uuid, p_idempotency_key text, p_response jsonb)
 RETURNS pos_financial_operations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.pos_financial_operations;
  v_session_id text;
  v_session public.pos_cash_sessions;
begin
  select * into v_operation from public.pos_financial_operations o
  where o.license_id = p_license_id and o.idempotency_key = p_idempotency_key
  for update;
  if v_operation.id is null then raise exception 'FINANCIAL_OPERATION_NOT_RESERVED' using errcode = 'P0001'; end if;
  if v_operation.status = 'completed' then return v_operation; end if;

  v_session_id := coalesce(p_response #>> '{cash_session,id}', p_response #>> '{cash_session_id}');
  if v_session_id is not null then
    select * into v_session from public.pos_cash_sessions s
    where s.license_id = p_license_id and s.id = v_session_id;
  end if;
  if v_operation.operation_type = 'cash.open' then
    if nullif(btrim(v_session_id), '') is null
       or v_session.id is null
       or v_session.cash_station_id is null
       or v_session.cash_station_id is distinct from v_operation.verified_cash_station_id then
      raise exception 'FINANCIAL_OPERATION_ORIGIN_MISMATCH' using errcode = 'P0001';
    end if;
  end if;
  update public.pos_financial_operations
  set status = 'completed', response_payload = p_response, completed_at = now(),
      verified_cash_session_id = coalesce(verified_cash_session_id, v_session.id),
      verified_cash_station_id = coalesce(verified_cash_station_id, v_session.cash_station_id)
  where id = v_operation.id
  returning * into v_operation;
  return v_operation;
end;
$function$

CREATE OR REPLACE FUNCTION private.financial_execution_request_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if jsonb_typeof(p_request) <> 'object' then
    raise exception 'FINANCIAL_REQUEST_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  return p_request;
end;
$function$

CREATE OR REPLACE FUNCTION private.public_financial_response_v1(p_operation_type text, p_response jsonb, p_external_idempotency_key text, p_internal_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_response jsonb; v_settlement jsonb;
begin
  perform private.assert_financial_legacy_result_terminal_v1(p_operation_type, p_response);

  if p_operation_type in (
    'layaway.create',
    'layaway.payment',
    'layaway.cancel',
    'sale.layaway_complete'
  ) then
    v_response := private.financial_layaway_response_allowlist_v2(p_operation_type, p_response);
  else
    v_response := private.sanitize_financial_response_idempotency_v1(
      p_response,
      p_external_idempotency_key,
      p_internal_idempotency_key
    );
    v_settlement := p_response->'restaurant_settlement';
    if jsonb_typeof(v_settlement) = 'object' then
      v_response := (v_response - 'restaurant_settlement') || jsonb_build_object(
        'restaurant_settlement', jsonb_strip_nulls(jsonb_build_object(
          'success', coalesce((v_settlement->>'success')::boolean, false),
          'parent_order_id', nullif(btrim(v_settlement->>'parent_order_id'), ''),
          'payment_status', nullif(btrim(v_settlement->>'payment_status'), ''),
          'paid_sale_id', nullif(btrim(v_settlement->>'paid_sale_id'), ''),
          'paid_sale_folio', nullif(btrim(v_settlement->>'paid_sale_folio'), ''),
          'total', case when nullif(v_settlement->>'total', '') is null then null else (v_settlement->>'total')::numeric end,
          'status', nullif(btrim(v_settlement->>'status'), ''),
          'fulfillment_status', nullif(btrim(v_settlement->>'fulfillment_status'), '')
        ))
      );
    end if;
  end if;

  perform private.assert_financial_response_no_internal_key_v1(
    v_response,
    p_internal_idempotency_key
  );

  return v_response || jsonb_build_object(
    'idempotency_key',
    p_external_idempotency_key
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.reserve_financial_operation_v1(p_license_id uuid, p_idempotency_key text, p_request_hash text, p_operation_type text, p_canonical_request jsonb, p_verified_actor_key text, p_verified_device_id uuid, p_cash_session_id text DEFAULT NULL::text, p_verified_cash_station_id text DEFAULT NULL::text)
 RETURNS pos_financial_operations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.pos_financial_operations;
  v_result public.pos_financial_operations;
  v_expected_hash text;
  v_session public.pos_cash_sessions;
  v_internal_idempotency_key text;
  v_operation_id uuid := extensions.gen_random_uuid();
begin
  if nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'FINANCIAL_IDEMPOTENCY_KEY_REQUIRED' using errcode = 'P0001';
  end if;
  perform private.assert_financial_request_hash_v1(p_request_hash);
  -- Reconstruct the origin-bound H from this invocation before considering an
  -- existing receipt.  A stale H may never turn a changed request into replay.
  if p_cash_session_id is not null then
    select * into v_session from public.pos_cash_sessions s
    where s.license_id = p_license_id and s.id = p_cash_session_id and s.deleted_at is null;
    if v_session.id is null then
      raise exception 'CASH_SESSION_NOT_FOUND' using errcode = 'P0001';
    end if;
  end if;

  v_expected_hash := private.financial_operation_hash(
    p_operation_type, p_canonical_request, p_verified_actor_key,
    p_cash_session_id, coalesce(v_session.cash_station_id, p_verified_cash_station_id)
  );
  if p_request_hash is distinct from v_expected_hash then
    raise exception 'FINANCIAL_REQUEST_HASH_INVALID' using errcode = 'P0001';
  end if;
  perform private.lock_financial_operation_v1(p_license_id, p_idempotency_key);

  -- Financial K/H state is authoritative and takes precedence over a generic
  -- idempotency row.  The latter is consulted only when no financial row exists.
  select * into v_existing from public.pos_financial_operations o
  where o.license_id = p_license_id and o.idempotency_key = p_idempotency_key
  for update;
  if v_existing.id is not null then
    if v_existing.legacy_idempotency_key is distinct from
       private.financial_operation_internal_key_v1(v_existing.operation_type, v_existing.id) then
      raise exception 'FINANCIAL_INTERNAL_IDEMPOTENCY_INTEGRITY' using errcode = 'P0001';
    end if;
    if v_existing.request_hash is distinct from p_request_hash then
      raise exception 'IDEMPOTENCY_CONFLICT' using errcode = 'P0001';
    end if;
    perform private.assert_financial_operation_origin_v1(
      v_existing, p_verified_actor_key, p_verified_device_id, p_cash_session_id
    );
    return v_existing;
  end if;

  -- A generic K in the external namespace predates strict V1 and cannot be
  -- adopted.  V1 itself writes only a server-owned internal namespace below.
  if exists (
    select 1 from public.pos_idempotency_keys k
  where k.license_id = p_license_id and k.idempotency_key = p_idempotency_key
  ) then raise exception 'LEGACY_IDEMPOTENCY_UNVERIFIED' using errcode = 'P0001'; end if;
  v_internal_idempotency_key := private.financial_operation_internal_key_v1(p_operation_type, v_operation_id);
  -- Never adopt a preexisting generic row in this server-generated namespace.
  -- With no strict owner above, this is a collision, not a replay.
  if exists (
    select 1 from public.pos_idempotency_keys k
    where k.license_id = p_license_id and k.idempotency_key = v_internal_idempotency_key
  ) then raise exception 'FINANCIAL_INTERNAL_IDEMPOTENCY_COLLISION' using errcode = 'P0001'; end if;

  insert into public.pos_financial_operations (
    id, license_id, idempotency_key, legacy_idempotency_key, request_hash, operation_type,
    verified_actor_key, verified_device_id, verified_cash_session_id, verified_cash_station_id,
    canonical_request
  ) values (
    v_operation_id, p_license_id, p_idempotency_key, v_internal_idempotency_key, p_request_hash, p_operation_type,
    p_verified_actor_key, p_verified_device_id, p_cash_session_id, coalesce(v_session.cash_station_id, p_verified_cash_station_id),
    p_canonical_request
  ) on conflict (license_id, idempotency_key) do nothing
  returning * into v_result;

  if v_result.id is null then
    raise exception 'FINANCIAL_OPERATION_RESERVATION_FAILED' using errcode = 'P0001';
  end if;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_financial_operation_origin_v1(p_operation pos_financial_operations, p_current_actor_key text, p_current_device_id uuid, p_requested_cash_session_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_station_id text;
begin
  -- Actor is strict V1 replay authority.  Any station-bound operation,
  -- including a cash.open that has not yet received its session id, must be
  -- recovered from a device currently bound to that exact active station.
  if p_operation.verified_actor_key is distinct from p_current_actor_key then
    raise exception 'FINANCIAL_OPERATION_ORIGIN_MISMATCH' using errcode = 'P0001';
  end if;
  if p_requested_cash_session_id is not null
     and p_operation.verified_cash_session_id is distinct from p_requested_cash_session_id then
    raise exception 'FINANCIAL_OPERATION_ORIGIN_MISMATCH' using errcode = 'P0001';
  end if;
  if p_operation.verified_cash_session_id is null
     and p_operation.verified_cash_station_id is null then return; end if;
  if p_operation.verified_cash_station_id is null or p_current_device_id is null then
    raise exception 'FINANCIAL_OPERATION_ORIGIN_MISMATCH' using errcode = 'P0001';
  end if;
  select b.cash_station_id into v_current_station_id
  from public.pos_cash_station_bindings b
  join public.pos_cash_stations s
    on s.license_id = b.license_id and s.id = b.cash_station_id
  where b.license_id = p_operation.license_id
    and b.device_id = p_current_device_id
    and b.status = 'active' and s.status = 'active'
  limit 1;
  if v_current_station_id is distinct from p_operation.verified_cash_station_id then
    raise exception 'FINANCIAL_OPERATION_ORIGIN_MISMATCH' using errcode = 'P0001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_financial_request_hash_v1(p_request_hash text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if nullif(btrim(p_request_hash), '') is null then
    raise exception 'FINANCIAL_REQUEST_HASH_REQUIRED' using errcode = 'P0001';
  end if;
  if p_request_hash !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'FINANCIAL_REQUEST_HASH_INVALID' using errcode = 'P0001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.financial_canonical_json_v1(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_key text; v_value jsonb; v_parts text[] := array[]::text[];
begin
  case jsonb_typeof(p_value)
    when 'object' then
      for v_key, v_value in select key, value from jsonb_each(p_value) order by key collate "C" loop
        v_parts := array_append(v_parts, to_jsonb(v_key)::text || ':' || private.financial_canonical_json_v1(v_value));
      end loop;
      return '{' || array_to_string(v_parts, ',') || '}';
    when 'array' then
      return '[' || coalesce((select string_agg(private.financial_canonical_json_v1(value), ',' order by ordinality) from jsonb_array_elements(p_value) with ordinality), '') || ']';
    else return p_value::text;
  end case;
end;
$function$

CREATE OR REPLACE FUNCTION private.financial_operation_internal_key_v1(p_operation_type text, p_operation_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if nullif(btrim(p_operation_type), '') is null or p_operation_id is null then
    raise exception 'FINANCIAL_IDEMPOTENCY_KEY_REQUIRED' using errcode = 'P0001';
  end if;
  return 'financial-v1:' || p_operation_type || ':' || p_operation_id::text;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_financial_legacy_result_terminal_v1(p_operation_type text, p_response jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_code text;
begin
  if jsonb_typeof(p_response) <> 'object' then
    raise exception 'FINANCIAL_LEGACY_RESPONSE_INVALID' using errcode = 'P0001';
  end if;
  v_code := nullif(btrim(p_response->>'code'), '');
  if v_code = 'IDEMPOTENCY_PROCESSING' then
    raise exception 'FINANCIAL_LEGACY_RESPONSE_NONTERMINAL' using errcode = 'P0001';
  end if;
  if (p_response->>'success')::boolean is not true then
    if p_response->'success' = 'false'::jsonb
       and p_operation_type = 'cash.admin_close'
       and v_code in ('VERSION_CONFLICT', 'CASH_TOTALS_CHANGED') then
      return;
    end if;
    raise exception 'FINANCIAL_LEGACY_OPERATION_REJECTED:%', coalesce(v_code, 'SUCCESS_FALSE') using errcode = 'P0001';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.sanitize_financial_response_idempotency_v1(p_value jsonb, p_external_idempotency_key text, p_internal_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_key text; v_value jsonb; v_result jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(p_value) = 'array' then
    return coalesce((select jsonb_agg(private.sanitize_financial_response_idempotency_v1(value, p_external_idempotency_key, p_internal_idempotency_key) order by ordinality) from jsonb_array_elements(p_value) with ordinality), '[]'::jsonb);
  end if;
  if jsonb_typeof(p_value) <> 'object' then return p_value; end if;
  for v_key, v_value in select key, value from jsonb_each(p_value) loop
    if lower(v_key) in ('idempotency_key','last_idempotency_key')
       and v_value = to_jsonb(p_internal_idempotency_key) then
      v_result := v_result || jsonb_build_object(v_key, p_external_idempotency_key);
    else
      v_result := v_result || jsonb_build_object(v_key, private.sanitize_financial_response_idempotency_v1(v_value, p_external_idempotency_key, p_internal_idempotency_key));
    end if;
  end loop;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_financial_response_no_internal_key_v1(p_value jsonb, p_internal_idempotency_key text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_key text; v_value jsonb;
begin
  if jsonb_typeof(p_value) = 'array' then
    for v_value in select value from jsonb_array_elements(p_value) loop perform private.assert_financial_response_no_internal_key_v1(v_value, p_internal_idempotency_key); end loop;
  elsif jsonb_typeof(p_value) = 'object' then
    for v_key, v_value in select key, value from jsonb_each(p_value) loop
      if lower(v_key) like '%idempotency_key' and v_value = to_jsonb(p_internal_idempotency_key) then
        raise exception 'FINANCIAL_INTERNAL_KEY_LEAK' using errcode = 'P0001';
      end if;
      perform private.assert_financial_response_no_internal_key_v1(v_value, p_internal_idempotency_key);
    end loop;
  end if;
end;
$function$
